insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-minor-cut','Small cut or graze','छोटा कट या खरोंच','first_aid','Small cut or graze','A small cut or scrape on the skin, for example from a kitchen knife, paper or a fall.',array['adult','child','older_adult']::text[],'All ages (extra care for babies)','Stop the bleeding with pressure, rinse the wound clean with water, and cover it with a clean plaster or dressing.','supported','Pressure, rinsing with clean water and a clean covering is standard first-aid advice from public health bodies such as the NHS.','["Wash and dry your hands first.","Press on the cut with a clean folded cloth or bandage until it stops bleeding. Raise a hand or arm above heart level if you can.","Rinse the cut with clean tap or bottled water. Pat dry with clean gauze or cloth.","Clean the skin around it with soap and water, wiping away from the wound.","Cover with a plaster or sterile dressing. Keep it clean and dry and change it when needed."]'::jsonb,'["Do not pull out anything stuck deep in the wound. Press around it and get help.","Do not pack the cut with powders, ash, coffee, or toothpaste.","Do not give aspirin to children under 16 for pain."]'::jsonb,'["Redness, swelling or pain that is getting worse after a day or two","Pus, or a bad smell from the wound","Feeling generally unwell or feverish"]'::jsonb,'["People on blood-thinning medicines may bleed longer. Seek advice if bleeding is hard to control."]'::jsonb,'["Bleeding that does not slow after 10 minutes of firm pressure","Blood spurting from the wound","A deep cut, a gaping wound, or one longer than about 5 cm","An object stuck in the wound","Numbness or cannot move fingers or toes normally"]'::jsonb,'["The wound has soil, pus or body fluids in it, or is still dirty after cleaning","It was caused by a human bite or a wild or stray animal","The cut is larger than about 5 cm, or on the face","Signs of infection: swelling, redness, increasing pain or pus"]'::jsonb,'[{"practice":"Applying haldi (turmeric) powder to a fresh cut","evidence":"traditional","note":"Widely used in Indian homes. There is not enough good evidence that turmeric on a wound helps it heal.","safety":"Loose powder can bring dirt into an open wound and may stain or irritate skin. Clean water and a clean dressing are the safer first step."}]'::jsonb,'{"child":"For children, keep the dressing on and check it daily. Get help if they will not let you clean it properly.","older_adult":"Older skin tears more easily and heals slower. Check the wound daily for signs of infection.","infant":"For a baby under 1, any cut that keeps bleeding or gapes should be seen by a doctor."}'::jsonb,null,'[{"id":"cut_flags","text":"Does any of this apply to the cut?","text_hi":"क्या इनमें से कुछ भी लागू होता है?","options":[{"label":"None of these: it is small and bleeding has slowed","label_hi":"इनमें से कुछ नहीं: छोटा है, खून कम हो गया","value":"none"},{"label":"Still bleeding after 10 minutes of firm pressure","label_hi":"10 मिनट दबाने पर भी खून बह रहा","value":"heavy","escalate":"urgent","reason":"Bleeding that does not stop with 10 minutes of pressure needs urgent medical care."},{"label":"Gaping, deep, or longer than about 5 cm","label_hi":"गहरा, खुला या 5 सेमी से लंबा","value":"deep","escalate":"urgent","reason":"Deep or gaping cuts may need stitches or glue. Get medical care today."},{"label":"Something is stuck in it","label_hi":"घाव में कुछ फँसा है","value":"object","escalate":"urgent","reason":"Do not remove objects stuck in a wound. Press around it and get medical help."},{"label":"Caused by an animal or human bite","label_hi":"जानवर या इंसान के काटने से","value":"bite","escalate":"urgent","reason":"Bites need medical assessment. Wash with soap and running water for 15 minutes and get care today."},{"label":"From a rusty or very dirty object","label_hi":"जंग लगी या गंदी चीज़ से","value":"dirty","escalate":"consider_advice","reason":"Dirty wounds carry an infection and tetanus risk. Ask a doctor or pharmacist about tetanus protection."}]}]'::jsonb,null,'self_care','[{"title":"Cuts and grazes","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/cuts-and-grazes/","supports":"Stopping bleeding, cleaning and dressing small wounds; when to get help."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['cut','graze','grazed','scrape','scraped','scraped knee','scratch','chhil gaya','chhil gayi','chhila','chhil','bleeding','knife','wound','paper cut','kat gaya','kat gayi','kat gai','ungli kat','ungli kat gayi','kaatte hue','cut lag gaya','chot','khoon','kharonch','chaku','कट','खरोंच','खून','घाव','चोट']::text[]);
