insert into public.knowledge_chunks (item_id,kind,content) values ('fa-minor-cut','keywords','cut graze grazed scrape scraped scraped knee scratch chhil gaya chhil gayi chhila chhil bleeding knife wound paper cut kat gaya kat gayi kat gai ungli kat ungli kat gayi kaatte hue cut lag gaya chot khoon kharonch chaku कट खरोंच खून घाव चोट');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-minor-burn','Small burn or scald','हल्का जलना','first_aid','Minor burn or scald','A small burn from a hot tawa, pressure cooker steam, hot oil, tea or an iron.',array['adult','child','older_adult']::text[],'All ages (children and babies need extra care)','Cool the burn under cool running water for 20 minutes as soon as possible, then cover it loosely with cling film or a clean non-fluffy covering.','supported','Cooling with running water for 20 minutes is standard first-aid guidance. Creams, oils and butter are advised against.','["Hold the burn under cool (not ice-cold) running water for 20 minutes. Start as soon as you can, ideally within 3 hours.","No running water? Use cool bottled water or a wet clean cloth.","Take off rings, bangles, watches or clothing near the burn, unless stuck to the skin.","Once cooled, lay cling film loosely over it. Do not wrap it tightly around a limb.","Keep the person warm otherwise, especially children. Cool the burn, not the whole body."]'::jsonb,'["Do not put toothpaste, butter, ghee, oil, flour, or creams on the burn.","Do not use ice or ice water.","Do not burst blisters.","Do not use sticky plasters or fluffy cotton on the burn."]'::jsonb,'["Increasing pain, redness or swelling after a day or two","Pus or a bad smell","Fever"]'::jsonb,'["Chemical and electrical burns are not covered here. They need emergency care."]'::jsonb,'["Burn larger than the palm of the hand of the person burned","Burn on the face, hands, feet, genitals, bottom, or over a joint","Deep burn: white, charred, leathery, or painless skin","Electrical or chemical burn","Any burn in a baby, or a burn with blistering in a young child","Breathing in smoke or steam, or a hoarse voice or cough after a fire"]'::jsonb,'["Any of the red flags above: go to emergency care","You are not sure how serious it is","Signs of infection while it heals"]'::jsonb,'[{"practice":"Toothpaste, ghee, butter or oil on a burn","evidence":"not_recommended","note":"Very common household advice. Public health guidance says not to put creams, oils or butter on burns.","safety":"These trap heat, can cause infection and make the burn harder for a doctor to assess."},{"practice":"Aloe vera gel on a healing minor burn","evidence":"limited","note":"Some people use plain aloe vera once the burn has fully cooled and the skin is intact.","safety":"Never as a replacement for 20 minutes of cool water. Do not use on broken skin or blisters. Stop if it irritates."}]'::jsonb,'{"child":"Children have thinner skin and burn more deeply. If the burn has blisters or is bigger than a coin, get it checked.","infant":"Any burn on a baby should be seen by a doctor.","older_adult":"Older skin burns more deeply and heals slower. Get larger or blistered burns checked."}'::jsonb,'[{"audience":"infant","reason":"Any burn on a baby should be assessed by a doctor.","escalate":"urgent"}]'::jsonb,'[{"id":"burn_flags","text":"Does any of this apply to the burn?","text_hi":"क्या इनमें से कुछ भी लागू होता है?","options":[{"label":"None of these: it is small, red and painful","label_hi":"इनमें से कुछ नहीं: छोटा, लाल और दर्द","value":"none"},{"label":"Bigger than the palm of the hand","label_hi":"हथेली से बड़ा","value":"large","escalate":"urgent","reason":"Burns bigger than the person’s palm need emergency care."},{"label":"On the face, hands, feet, genitals or a joint","label_hi":"चेहरे, हाथ, पैर, गुप्तांग या जोड़ पर","value":"sensitive","escalate":"urgent","reason":"Burns in these areas need to be seen by a doctor."},{"label":"Caused by electricity or a chemical","label_hi":"बिजली या केमिकल से","value":"chem","escalate":"urgent","reason":"Electrical and chemical burns always need emergency care."},{"label":"Skin is white, charred, leathery, or does not hurt","label_hi":"त्वचा सफ़ेद, काली, सख़्त या दर्द नहीं","value":"deep","escalate":"urgent","reason":"These can be signs of a deep burn. Get emergency care."}]}]'::jsonb,null,'self_care','[{"title":"Burns and scalds","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/burns-and-scalds/","supports":"Cool running water for 20 minutes; no creams, oils or butter; when to go to A&E."},{"title":"Aloe Vera: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/aloe-vera","supports":"Topical aloe is promoted for burns; oral aloe may be unsafe in pregnancy."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['burn','burnt','burned','burns','burned my','burnt my','burned my finger','while cooking','finger is burning','hand is burning','skin is burning','touched','touching','hot pan','stove','hot chai','hot tea','hot water','hot milk','spilled hot','scald','scalded','hot oil','tawa','steam','pressure cooker','iron','jal gaya','jal gayi','jala','jalna','garam','chai gir gayi','जल गया','जला','जलना','छाला']::text[]);
