insert into public.knowledge_chunks (item_id,kind,content) values ('fa-minor-burn','keywords','burn burnt burned burns burned my burnt my burned my finger while cooking finger is burning hand is burning skin is burning touched touching hot pan stove hot chai hot tea hot water hot milk spilled hot scald scalded hot oil tawa steam pressure cooker iron jal gaya jal gayi jala jalna garam chai gir gayi जल गया जला जलना छाला');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-bruise','Bruise or bump','नील या गुमड़ा','first_aid','Bruise or minor bump','A blue, purple or dark mark after bumping into something or a minor fall.',array['adult','child','older_adult']::text[],'All ages','Rest the area and apply a cold pack wrapped in cloth to reduce swelling and pain. Most bruises fade on their own over one to two weeks.','supported','Cold compresses and rest are standard first-aid advice for bruises. Bruises normally fade without treatment.','["Hold a cold pack or frozen peas wrapped in a cloth on the area for up to 20 minutes.","Rest and, if possible, raise the bruised part.","Repeat the cold pack a few times over the first day or two."]'::jsonb,'["Do not put ice directly on skin.","Do not massage a fresh bruise hard."]'::jsonb,'["Swelling that keeps growing","Pain that is getting worse instead of better","Bruises that appear without any injury"]'::jsonb,'["People on blood thinners bruise more easily and should mention unexplained bruises to their doctor."]'::jsonb,'["Bruise after a head injury with drowsiness, vomiting, confusion or severe headache","Cannot move or put weight on the injured part","Very large swelling or a deformed-looking limb","Unexplained bruising, especially with bleeding gums or nosebleeds"]'::jsonb,'["Bruising appears for no reason or very easily","Pain and swelling are severe or not improving after a few days","Injury to the eye area or head"]'::jsonb,'[{"practice":"Haldi (turmeric) lep on a bruise","evidence":"traditional","note":"Common household practice. Evidence that turmeric on the skin speeds healing of bruises is not established.","safety":"Usually harmless on unbroken skin but can stain. Do not use on open wounds. Stop if the skin gets irritated."}]'::jsonb,'{"child":"A child with a bump on the head who is drowsy, vomits, or acts unusually needs urgent medical care.","older_adult":"Falls in older adults can cause hidden injuries. Watch for new confusion or pain on walking."}'::jsonb,null,'[{"id":"head","text":"Was it a hit to the head?","text_hi":"क्या सिर पर चोट लगी?","options":[{"label":"No","value":"no"},{"label":"Yes, and they seem normal","value":"head_ok","escalate":"consider_advice","reason":"Watch closely for 24 hours after a head bump. Get urgent help for drowsiness, vomiting or confusion."},{"label":"Yes, with vomiting, drowsiness, confusion or fainting","value":"head_bad","escalate":"urgent","reason":"These are warning signs after a head injury. Get emergency care now."}]},{"id":"move","text":"Can the injured part move and take weight normally?","options":[{"label":"Yes","value":"yes"},{"label":"No, or it looks out of shape","value":"no","escalate":"urgent","reason":"This could be a fracture. Get it checked."}]}]'::jsonb,null,'self_care','[{"title":"Bruises","publisher":"MedlinePlus (US National Library of Medicine)","url":"https://medlineplus.gov/bruises.html","supports":"What bruises are and how they are usually managed."},{"title":"First aid advice","publisher":"St John Ambulance","url":"https://www.sja.org.uk/get-advice/first-aid-advice/","supports":"General first-aid reference (bruises, splinters, sprains)."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['bruise','bump','blue mark','hit','knock','neel','neela','gumda','takra gaya','lag gayi','sujan','नील','गुमड़ा','सूजन','टकरा']::text[]);
