insert into public.knowledge_chunks (item_id,kind,content) values ('fa-bruise','problem','A blue, purple or dark mark after bumping into something or a minor fall.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-bruise','keywords','bruise bump blue mark hit knock neel neela gumda takra gaya lag gayi sujan नील गुमड़ा सूजन टकरा');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-blister','Blister','फफोला / छाला','first_aid','Friction blister','A small bubble of fluid under the skin, usually from new shoes or rubbing.',array['adult','child','older_adult']::text[],'All ages','Leave the blister intact, keep it clean, and cover it with a soft or padded plaster. Most heal within a week.','supported','NHS guidance: do not burst blisters, keep them clean and covered, and avoid whatever caused the rubbing until healed.','["Gently wash the area and pat it dry.","Cover with a soft plaster or padded dressing.","If it bursts on its own, let the fluid drain, do not peel the skin, and cover it.","Avoid the shoes or activity that caused it until it heals."]'::jsonb,'["Do not burst it with a needle or pin.","Do not peel off the loose skin.","Do not pick at the edges."]'::jsonb,'["Yellow or green pus","Skin around it becoming hot, red or more painful"]'::jsonb,'["People with diabetes or poor circulation should get foot blisters checked."]'::jsonb,'["Blisters from a burn, sunburn or allergic reaction","Blisters on the eyelids, mouth or genitals","Many blisters appearing for no reason"]'::jsonb,'["The blister looks infected","It is very painful or keeps coming back","You have diabetes and the blister is on your foot"]'::jsonb,null,null,null,'[{"id":"cause","text":"What caused the blister?","options":[{"label":"Shoes or rubbing","value":"friction"},{"label":"A burn or sunburn","value":"burn","escalate":"consider_advice","reason":"Blisters from burns are treated as burns. See the burn guide and get larger ones checked."},{"label":"No clear reason, or many appeared","value":"unknown","escalate":"consider_advice","reason":"Blisters that appear for no reason should be checked by a doctor."}]}]'::jsonb,null,'self_care','[{"title":"Blisters","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/blisters/","supports":"Keeping blisters clean and covered; not bursting them; signs of infection."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['blister','shoe bite','rubbing','chhala','chhale','phaphola','joote se','shoe bite ho gaya','छाला','फफोला']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-blister','summary','Blister. Friction blister. Leave the blister intact, keep it clean, and cover it with a soft or padded plaster. Most heal within a week.');
