insert into public.knowledge_chunks (item_id,kind,content) values ('fa-blister','keywords','blister shoe bite rubbing chhala chhale phaphola joote se shoe bite ho gaya छाला फफोला');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-splinter','Small splinter','फांस / छोटा कांटा','first_aid','Small surface splinter','A small piece of wood, thorn or glass just under the surface of the skin.',array['adult','child','older_adult']::text[],'All ages','If the end is visible and shallow, clean the area and pull it out in the same direction it went in with clean tweezers, then wash and cover.','limited','Removal of shallow splinters with clean tweezers is common first-aid practice (St John Ambulance). We did not find a verified source page for exact steps, so this guide is marked for expert review.','["Wash your hands and the skin with soap and water.","Clean tweezers with soap and hot water or an alcohol wipe.","Grip the visible end and pull it out gently at the same angle it went in.","Squeeze gently so a little blood flushes the wound, then wash and cover with a plaster."]'::jsonb,'["Do not dig deep with a needle.","Do not try to remove glass or metal that is deep or near the eye."]'::jsonb,'["Redness, swelling, pus or throbbing over the next days","A piece left behind"]'::jsonb,'["People with diabetes should get foot splinters checked."]'::jsonb,'["Splinter in or near the eye","Deeply embedded splinter, glass or metal","Splinter under a fingernail that cannot be reached"]'::jsonb,'["You cannot get it out","Signs of infection","Tetanus protection may not be up to date and the object was dirty"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"First aid advice","publisher":"St John Ambulance","url":"https://www.sja.org.uk/get-advice/first-aid-advice/","supports":"General first-aid reference (bruises, splinters, sprains)."}]'::jsonb,'public_health_body','2026-09-26','needs_source','en',array['splinter','thorn','wood piece','glass piece','phaans','phans','kaanta','kanta chubh gaya','chubh gaya','फांस','कांटा','चुभ']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-splinter','summary','Small splinter. Small surface splinter. If the end is visible and shallow, clean the area and pull it out in the same direction it went in with clean tweezers, then wash and cover.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-splinter','problem','A small piece of wood, thorn or glass just under the surface of the skin.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-splinter','keywords','splinter thorn wood piece glass piece phaans phans kaanta kanta chubh gaya chubh gaya फांस कांटा चुभ');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-insect-bite','Mosquito or insect bite','मच्छर या कीड़े का काटना','first_aid','Insect or mosquito bite','An itchy or painful red bump from a mosquito, ant, bed bug or similar insect.',array['adult','child','older_adult']::text[],'All ages','Wash the bite with soap and water, hold a cold compress on it, and try not to scratch. Most bites settle within a few days.','supported','NHS guidance: wash the area, apply a cold compress, avoid scratching. A pharmacist can suggest anti-itch options.','["Wash the area with soap and water.","Hold a cold compress (a cloth soaked in cold water, or ice wrapped in cloth) on it for at least 10 minutes.","Raise the area if it is swollen.","Keep nails short, especially for children, to avoid breaking the skin by scratching.","A pharmacist can suggest suitable anti-itch creams or antihistamines if the itch is bad."]'::jsonb,'["Do not scratch: it can cause infection.","Do not apply kerosene, petrol or strong chemicals.","Do not use home remedies like bicarbonate of soda on the bite (NHS advises against it)."]'::jsonb,'["Redness or swelling spreading over the next days","Pus, or feeling unwell","Fever in the days or week after mosquito bites"]'::jsonb,'[]'::jsonb,'["Swelling of the lips, tongue, face or throat","Difficulty breathing or wheezing","Feeling faint, dizzy or confused after a bite or sting","High fever, severe body ache or pain behind the eyes in the days after mosquito bites (possible dengue or malaria)"]'::jsonb,'["Symptoms are not improving after a few days, or are getting worse","Signs of infection, like pus or spreading redness","A fever in the days after being bitten, especially in monsoon","Bitten in the mouth or throat, or near the eyes"]'::jsonb,'[{"practice":"Neem leaves or neem oil for bites and to keep mosquitoes away","evidence":"limited","note":"Neem is traditionally used against insects. Some small studies suggest a repellent effect, but it is less proven than standard repellents.","safety":"Do not rely on neem alone in dengue or malaria season. Patch-test first, and do not use neem oil on babies."}]'::jsonb,'{"child":"Keep children’s nails short and watch for fever in the days after bites during monsoon.","infant":"For babies, use nets and covering clothes. Ask a doctor or pharmacist before using any repellent or cream."}'::jsonb,null,'[{"id":"reaction","text":"Any swelling of the face, lips or throat, or trouble breathing?","text_hi":"क्या चेहरे, होंठ या गले में सूजन या सांस लेने में तकलीफ़ है?","options":[{"label":"No, just a local itchy bump","value":"local"},{"label":"Yes","value":"anaphylaxis","escalate":"urgent","reason":"This can be a severe allergic reaction. Call 112 now."}]},{"id":"fever","text":"Any fever since the bites?","text_hi":"क्या काटने के बाद बुखार आया?","options":[{"label":"No fever","value":"no"},{"label":"Yes, fever or body ache","value":"fever","escalate":"consider_advice","reason":"Fever after mosquito bites can signal dengue or malaria. See a doctor for testing."}]}]'::jsonb,null,'self_care','[{"title":"Insect bites and stings","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/insect-bites-and-stings/","supports":"Removing stings, cold compress, not scratching, allergic-reaction warning signs."},{"title":"Dengue and severe dengue (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/dengue-and-severe-dengue","supports":"Covering skin, nets, repellents (DEET, picaridin, IR3535), emptying stored water weekly."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['mosquito','mosquito bite','mosquito bites','bites all over','insect bite','bug bite','ant bite','ants','ant','ants bit','bed bug','itchy bump','itching','itch','machhar','machchar','machar','keeda','keede ne kaata','kaat liya','kaata','khujli','chinti','मच्छर','कीड़ा','काट','खुजली','चींटी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-insect-bite','summary','Mosquito or insect bite. Insect or mosquito bite. Wash the bite with soap and water, hold a cold compress on it, and try not to scratch. Most bites settle within a few days.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-insect-bite','problem','An itchy or painful red bump from a mosquito, ant, bed bug or similar insect.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-insect-bite','keywords','mosquito mosquito bite mosquito bites bites all over insect bite bug bite ant bite ants ant ants bit bed bug itchy bump itching itch machhar machchar machar keeda keede ne kaata kaat liya kaata khujli chinti मच्छर कीड़ा काट खुजली चींटी');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-sting','Bee or wasp sting','मधुमक्खी या ततैया का डंक','first_aid','Bee or wasp sting','A painful sting from a bee, wasp (tatiya) or hornet.',array['adult','child','older_adult']::text[],'All ages','Remove any sting left in the skin by scraping sideways, wash the area, and apply a cold compress. Watch closely for signs of a severe allergic reaction.','supported','NHS guidance covers removing the sting, cold compress, and emergency signs of anaphylaxis.','["If the sting is still in the skin, scrape it out sideways with a fingernail or card edge. Do not squeeze it with fingers.","Wash the area with soap and water.","Hold a cold compress on it for at least 10 minutes. Raise the area if swollen.","Keep watching for any breathing or swelling problems for the next hour."]'::jsonb,'["Do not squeeze the sting with tweezers or fingers.","Do not scratch.","Do not apply kerosene or chemicals."]'::jsonb,'["Swelling spreading over a larger area over a day or two","Signs of infection"]'::jsonb,'["Anyone with a known sting allergy should follow their doctor’s emergency plan."]'::jsonb,'["Swelling of the lips, tongue, face or throat","Difficulty breathing, wheezing or a tight throat","Dizziness, fainting, or a fast heartbeat","Many stings at once, or a sting inside the mouth or throat"]'::jsonb,'["Large swelling that spreads a lot","Signs of infection","Known allergy to stings"]'::jsonb,null,null,null,'[{"id":"reaction","text":"Any swelling of the face, lips or throat, dizziness, or trouble breathing?","text_hi":"क्या चेहरे/गले में सूजन, चक्कर या सांस की तकलीफ़ है?","options":[{"label":"No, just pain and swelling where stung","value":"local"},{"label":"Yes","value":"anaphylaxis","escalate":"urgent","reason":"This can be anaphylaxis, a life-threatening allergic reaction. Call 112 now."}]},{"id":"count","text":"How many stings, and where?","options":[{"label":"One or a few on the skin","value":"few"},{"label":"Many stings, or inside the mouth or throat","value":"many","escalate":"urgent","reason":"Many stings or stings in the mouth need emergency care."}]}]'::jsonb,null,'self_care','[{"title":"Insect bites and stings","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/insect-bites-and-stings/","supports":"Removing stings, cold compress, not scratching, allergic-reaction warning signs."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['bee sting','wasp','hornet','sting','stung','madhumakkhi','makkhi ne kaata','tatiya','tatiyaa','bhirh','dank','डंक','मधुमक्खी','ततैया','बर्र']::text[]);
