insert into public.knowledge_chunks (item_id,kind,content) values ('fa-sting','keywords','bee sting wasp hornet sting stung madhumakkhi makkhi ne kaata tatiya tatiyaa bhirh dank डंक मधुमक्खी ततैया बर्र');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-sprain','Minor sprain or twisted ankle','मोच','first_aid','Minor sprain or strain','A twisted ankle, wrist or knee with pain and some swelling, where you can still move it.',array['adult','child','older_adult']::text[],'All ages','For the first 2–3 days, follow PRICE: Protect, Rest, Ice (wrapped), Compression, Elevation. Most sprains feel better within 2 weeks.','supported','PRICE is the NHS-recommended self-care approach for sprains and strains in the first 2–3 days.','["Protect: support the joint, e.g. with a supportive shoe.","Rest: stop the activity and avoid putting weight on it.","Ice: a cold pack or frozen peas in a cloth for up to 20 minutes every 2–3 hours.","Compression: a bandage for support during the day (not too tight).","Elevate: keep it raised on a pillow when you can.","Once you can move it without much pain, keep it gently moving so it does not stiffen."]'::jsonb,'["For the first couple of days avoid heat (hot baths, heat packs), alcohol and massage.","Avoid strenuous exercise like running for several weeks."]'::jsonb,'["Pain or swelling getting worse","No improvement after a few days"]'::jsonb,'[]'::jsonb,'["Cannot put any weight on it or walk more than a few steps","The joint looks deformed or out of place","Heard a crack or snap at the time of injury","Numbness, tingling, or the skin below turns pale or cold","Fever or feeling hot and shivery with the swelling"]'::jsonb,'["It is very painful or getting worse","Large or worsening swelling or bruising","It is not improving after treating it yourself"]'::jsonb,'[{"practice":"Hot haldi-chuna (turmeric and lime) lep or hot oil massage right after a sprain","evidence":"traditional","note":"Very common in Indian homes. There is no good evidence it speeds healing.","safety":"Heat and massage in the first 2 days may increase swelling. Lime (chuna) can burn skin. Prefer a cold pack early on."}]'::jsonb,null,null,'[{"id":"weight","text":"Can you put weight on it or use it a little?","text_hi":"क्या उस पर थोड़ा वज़न डाल पा रहे हैं?","options":[{"label":"Yes, with some pain","value":"yes"},{"label":"No, or it looks out of shape","value":"no","escalate":"urgent","reason":"This could be a fracture or dislocation. Get it checked today."}]}]'::jsonb,null,'self_care','[{"title":"Sprains and strains","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/sprains-and-strains/","supports":"PRICE steps for the first 2–3 days and when to get help."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['sprain','twisted ankle','strain','pulled muscle','ankle','wrist','moch','moch aa gayi','pair mud gaya','mud gaya','मोच','मुड़ गया','टखना']::text[]);
