insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-nosebleed','Nosebleed','नकसीर','first_aid','Nosebleed','Bleeding from the nose, often from dry air, heat, nose picking or blowing hard.',array['adult','child','older_adult']::text[],'All ages (under 2s should see a doctor)','Sit down, lean forward, and pinch the soft part of the nose just above the nostrils for 10–15 minutes while breathing through the mouth.','supported','The lean-forward-and-pinch method is NHS guidance. Ice on the bridge of the nose may help but evidence is weak.','["Sit down and lean forward, with the head tilted forward and mouth open.","Pinch the soft part of the nose just above the nostrils for 10–15 minutes without letting go.","Breathe through your mouth and spit out any blood.","Optional: a cold pack on the top of the nose.","For 24 hours after, avoid blowing or picking the nose, hot drinks, alcohol and heavy lifting."]'::jsonb,'["Do not tilt the head back (blood runs down the throat).","Do not lie flat.","Do not stuff cotton deep into the nose."]'::jsonb,'["Nosebleeds that keep coming back","Unusual tiredness or paleness"]'::jsonb,'["People on blood thinners like warfarin should seek advice for any nosebleed."]'::jsonb,'["Bleeding longer than 10–15 minutes despite pinching","Heavy bleeding or swallowing a lot of blood causing vomiting","Nosebleed after a blow to the head","Feeling weak, dizzy or having trouble breathing"]'::jsonb,'["Nosebleeds happen regularly","A child under 2 has a nosebleed","You take blood-thinning medicine"]'::jsonb,'[{"practice":"Tilting the head back, or pouring cold water on the head","evidence":"not_recommended","note":"Tilting back is a common instinct, but guidance is to lean forward.","safety":"Tilting back makes you swallow blood, which can cause vomiting and hides how much you are bleeding."}]'::jsonb,null,'[{"audience":"infant","reason":"A nosebleed in a child under 2 should be checked by a doctor.","escalate":"consider_advice"}]'::jsonb,'[{"id":"duration","text":"Has it stopped after 10–15 minutes of pinching?","text_hi":"10-15 मिनट दबाने पर खून रुका?","options":[{"label":"Yes, or I have not tried yet","value":"ok"},{"label":"No, still bleeding heavily","value":"long","escalate":"urgent","reason":"Bleeding over 15 minutes needs emergency care."}]},{"id":"injury","text":"Did it start after a blow to the head or face?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"A nosebleed after a head injury needs emergency assessment."}]}]'::jsonb,null,'self_care','[{"title":"Nosebleed","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/nosebleed/","supports":"Lean forward, pinch the soft part of the nose for 10–15 minutes; when to go to A&E."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['nosebleed','nose bleed','bleeding nose','blood from nose','naksir','nakseer','naak se khoon','nak se khoon','नकसीर','नाक से खून']::text[]);
