insert into public.knowledge_chunks (item_id,kind,content) values ('fa-nosebleed','keywords','nosebleed nose bleed bleeding nose blood from nose naksir nakseer naak se khoon nak se khoon नकसीर नाक से खून');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fa-muscle-soreness','Muscle soreness after activity','मांसपेशियों में दर्द','first_aid','Muscle soreness after exercise or work','Aching, stiff muscles a day or two after exercise, a long walk, or heavy housework.',array['adult','older_adult','child']::text[],'All ages','This usually eases on its own in a few days. Gentle movement, stretching, rest and fluids help. Build up activity gradually.','limited','Delayed muscle soreness is common and self-limiting. Evidence for any specific remedy (massage, stretching, heat) speeding recovery is modest.','["Keep moving gently: a light walk helps more than complete rest.","Gentle stretching within comfort.","A warm bath or a wrapped hot water bottle can ease stiffness (not for fresh injuries with swelling).","Drink enough water and sleep well.","Next time, warm up first and increase effort gradually."]'::jsonb,'["Do not push through sharp or sudden pain.","Do not use heat on a fresh injury with swelling."]'::jsonb,'["Pain that does not ease after a week","Swelling in one spot"]'::jsonb,'[]'::jsonb,'["Very dark (cola-coloured) urine after hard exercise","Severe muscle pain with weakness or swelling","Chest pain, or pain spreading to the arm, jaw or back"]'::jsonb,'["Pain lasts more than a week or is getting worse","You felt a sudden pop or sharp pain during activity"]'::jsonb,'[{"practice":"Warm sarson (mustard) oil massage for sore muscles","evidence":"traditional","note":"Common in many Indian homes. Massage in general may ease soreness for some people; evidence for the oil itself is limited.","safety":"Use warm, not hot, oil. Mustard oil can irritate some skin. Not for babies’ faces, broken skin or fresh swollen injuries."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Physical activity guidelines for adults aged 19 to 64","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/live-well/exercise/exercise-guidelines/physical-activity-guidelines-for-adults-aged-19-to-64/","supports":"Breaking up long periods of sitting; weekly activity targets."}]'::jsonb,'public_health_body','2026-09-26','needs_source','en',array['muscle pain','sore muscles','body ache after gym','stiffness','aching','gym ke baad dard','badan dard','maaspeshi','mansapeshi','sharir dard','पैर दर्द','बदन दर्द','मांसपेशी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-muscle-soreness','summary','Muscle soreness after activity. Muscle soreness after exercise or work. This usually eases on its own in a few days. Gentle movement, stretching, rest and fluids help. Build up activity gradually.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-muscle-soreness','problem','Aching, stiff muscles a day or two after exercise, a long walk, or heavy housework.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fa-muscle-soreness','keywords','muscle pain sore muscles body ache after gym stiffness aching gym ke baad dard badan dard maaspeshi mansapeshi sharir dard पैर दर्द बदन दर्द मांसपेशी');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-sore-throat','Sore throat','गले में खराश','discomfort','Sore throat','Scratchy, painful throat, often with a cold. Usually gets better within a week.',array['adult','child','older_adult']::text[],'All ages (salt-water gargle for adults and older children only)','Rest, drink plenty of water, eat cool or soft foods, and (for adults) gargle with warm salty water. Most sore throats clear up within a week.','supported','NHS self-care advice for sore throat: fluids, soft foods, rest, salt-water gargles for adults. Antibiotics are usually not needed.','["Drink plenty of water and warm (not hot) fluids.","Adults: gargle with half a teaspoon of salt in a glass of warm water, then spit it out.","Eat cool or soft foods.","Rest, and avoid smoke and smoky kitchens.","A pharmacist can suggest lozenges or pain relief suitable for you."]'::jsonb,'["Children should not gargle salt water.","Do not give young children hard sweets or anything small and hard (choking risk).","Do not ask for antibiotics for an ordinary sore throat: they usually do not help."]'::jsonb,'["Not improving after a week","High temperature, or feeling hot and shivery","Signs of dehydration: peeing less, dark urine"]'::jsonb,'[]'::jsonb,'["Difficulty breathing","Unable to swallow, or drooling","A high-pitched sound when breathing in","Severe symptoms that are getting worse quickly"]'::jsonb,'["Not better after a week","Sore throats happen often","A child under 5 needs help for a sore throat","A lump in the neck or a mouth ulcer lasting more than 3 weeks","Weakened immune system (e.g. diabetes, chemotherapy)"]'::jsonb,'[{"practice":"Haldi doodh (turmeric milk) for a sore throat","evidence":"traditional","note":"A comforting household drink. Warm drinks can soothe; there is no strong evidence that turmeric itself treats sore throats.","safety":"Fine as a warm drink for most people. Serve warm, not hot, to children."},{"practice":"Namak ke paani se garare (salt-water gargle)","evidence":"supported","note":"Recommended by NHS guidance for adults to soothe a sore throat.","safety":"Not for children. Spit it out, do not swallow."},{"practice":"Adrak-tulsi-shahad (ginger, tulsi, honey) kadha","evidence":"traditional","note":"Warm drinks and honey may soothe the throat. Evidence for tulsi and ginger specifically for sore throat is limited.","safety":"No honey for babies under 1 year. Keep it warm, not scalding."}]'::jsonb,'{"child":"No salt-water gargles for children. Get advice for a child under 5 with a sore throat.","infant":"For babies with a sore throat or poor feeding, speak to a doctor."}'::jsonb,'[{"audience":"infant","reason":"Babies with a sore throat or who are not feeding well should be seen by a doctor.","escalate":"consider_advice"}]'::jsonb,'[{"id":"breathing","text":"Any difficulty breathing or swallowing, or drooling?","text_hi":"क्या सांस लेने या निगलने में दिक्कत है, या लार टपक रही है?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Trouble breathing or swallowing with a sore throat needs emergency care."}]},{"id":"fever","text":"Is there a high fever, or does the person feel very unwell?","text_hi":"क्या तेज़ बुखार है या बहुत ज़्यादा तबीयत ख़राब लग रही है?","options":[{"label":"No, feeling mostly okay","value":"no"},{"label":"Yes, high fever or feeling very unwell","value":"yes","escalate":"consider_advice","reason":"A high fever or feeling very unwell is a reason to speak to a doctor."}]}]'::jsonb,null,'self_care','[{"title":"Sore throat","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/sore-throat/","supports":"Salt-water gargles for adults (not children), fluids, rest; emergency signs."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['sore throat','throat pain','scratchy throat','throat infection','gala','gala kharab','gale mein dard','gale me dard','gala dukh raha','khich khich','kharash','गला','गले में दर्द','खराश','गला खराब']::text[]);
