insert into public.knowledge_chunks (item_id,kind,content) values ('dc-sore-throat','problem','Scratchy, painful throat, often with a cold. Usually gets better within a week.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-sore-throat','keywords','sore throat throat pain scratchy throat throat infection gala gala kharab gale mein dard gale me dard gala dukh raha khich khich kharash गला गले में दर्द खराश गला खराब');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-mild-cough','Mild cough','हल्की खांसी','discomfort','Mild cough','A cough, often with a cold. Most coughs clear up within 3–4 weeks.',array['adult','child','older_adult']::text[],'All ages (no honey under 1 year)','Rest and drink plenty of fluids. For adults and children over 1, warm water with lemon and honey may ease the cough.','supported','NHS advice: rest and fluids. Honey and lemon may help, though evidence is limited. Paediatric guidance supports honey for children aged 1 and older.','["Rest and drink plenty of fluids.","Warm water with half a lemon and 1–2 teaspoons of honey (not for babies under 1).","Stay home and avoid close contact if you have a high temperature.","Ask a pharmacist before using any cough medicine, especially for children."]'::jsonb,'["Never give honey to a baby under 1 year old (risk of infant botulism).","Do not give over-the-counter cough and cold medicines to young children without a doctor’s or pharmacist’s advice.","Do not let children breathe steam from a bowl of hot water (scald risk).","Do not smoke or stay in smoky rooms."]'::jsonb,'["Cough lasting more than 3 weeks","Losing weight without trying"]'::jsonb,'[]'::jsonb,'["Difficulty breathing or breathing very fast","Chest pain","Coughing up blood","Blue or grey lips, face or tongue","A baby with a cough who is struggling to breathe or not feeding"]'::jsonb,'["Cough for more than 3 weeks","Cough is very bad or quickly getting worse","You feel very unwell, or the side of the neck is swollen and painful","Weakened immune system"]'::jsonb,'[{"practice":"Shahad (honey) for cough","evidence":"limited","note":"Supported by NHS and American Academy of Pediatrics guidance as a reasonable home option for ages 1 and up, though evidence is limited.","safety":"NEVER for babies under 12 months. It can cause infant botulism."},{"practice":"Bhaap lena (steam inhalation) from a bowl of hot water","evidence":"limited","note":"Steam from a hot shower may ease a blocked nose for adults.","safety":"Do not let children breathe steam from a bowl of hot water: scald risk. Children get serious burns this way."}]'::jsonb,'{"child":"Honey is fine for children aged 1 and older. Avoid over-the-counter cough medicines unless advised.","infant":"No honey. A baby under 3 months with a cough, or any baby struggling to breathe, should be seen by a doctor.","older_adult":"Older adults with a cough and breathlessness, fever or confusion should see a doctor."}'::jsonb,'[{"audience":"infant","reason":"Babies with a cough should be assessed by a doctor, especially under 3 months. No honey under 1 year.","escalate":"consider_advice"}]'::jsonb,'[{"id":"breathing","text":"Any difficulty breathing, chest pain, or coughing up blood?","text_hi":"क्या सांस लेने में दिक्कत, सीने में दर्द या खांसी में खून है?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Breathing difficulty, chest pain or coughing blood needs urgent medical care."}]},{"id":"fever","text":"Is there a high fever, or does the person feel very unwell?","text_hi":"क्या तेज़ बुखार है या बहुत ज़्यादा तबीयत ख़राब लग रही है?","options":[{"label":"No, feeling mostly okay","value":"no"},{"label":"Yes, high fever or feeling very unwell","value":"yes","escalate":"consider_advice","reason":"A high fever or feeling very unwell is a reason to speak to a doctor."}]}]'::jsonb,null,'self_care','[{"title":"Cough","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/cough/","supports":"Rest, fluids, lemon and honey (not under 1 year, limited evidence); when to see a doctor."},{"title":"Coughs and Colds: Medicines or Home Remedies?","publisher":"HealthyChildren.org (American Academy of Pediatrics)","url":"https://www.healthychildren.org/English/health-issues/conditions/chest-lungs/Pages/Coughs-and-Colds-Medicines-or-Home-Remedies.aspx","supports":"No honey under 1 year; honey may help cough in children aged 1 and older."},{"title":"Common cold","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/common-cold/","supports":"Rest, fluids; do not let children breathe steam from a bowl (scald risk); no honey under 12 months."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['cough','coughing','dry cough','wet cough','khansi','khaansi','khasi','khaasi','balgam','khaans','खांसी','खाँसी','बलगम']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-cough','summary','Mild cough. Mild cough. Rest and drink plenty of fluids. For adults and children over 1, warm water with lemon and honey may ease the cough.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-cough','problem','A cough, often with a cold. Most coughs clear up within 3–4 weeks.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-cough','keywords','cough coughing dry cough wet cough khansi khaansi khasi khaasi balgam khaans खांसी खाँसी बलगम');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-common-cold','Common cold','सर्दी-ज़ुकाम','discomfort','Common cold','Blocked or runny nose, sneezing, mild sore throat, feeling tired. Usually better in 1–2 weeks.',array['adult','child','older_adult']::text[],'All ages','Rest, drink plenty of fluids and eat well. Steam from a hot shower can ease a blocked nose for adults. Most colds get better in 1–2 weeks.','supported','NHS self-care advice for colds. There is little evidence that vitamin C, echinacea or garlic prevent or shorten colds.','["Rest and drink plenty of water and warm fluids.","Eat healthy food. It is common for children to eat less for a few days.","Adults: sit in a steamy bathroom with a hot shower running to ease a blocked nose.","Adults: salt-water gargles for a sore throat.","Ask a pharmacist about suitable medicines. Do not combine several cold medicines with paracetamol."]'::jsonb,'["Do not let children breathe steam from a bowl of hot water (scald risk).","Do not give aspirin to children under 16.","Do not give honey to babies under 12 months.","Antibiotics do not treat colds."]'::jsonb,'["Symptoms lasting more than 3 weeks","Symptoms getting worse instead of better"]'::jsonb,'[]'::jsonb,'["Difficulty breathing","Chest pain","A baby under 3 months with a high temperature","Confusion or drowsiness"]'::jsonb,'["Symptoms do not improve after 3 weeks","Symptoms suddenly get worse","High temperature for more than a few days","Long-term condition such as diabetes, heart or lung disease"]'::jsonb,'[{"practice":"Tulsi (holy basil) chai or kadha for a cold","evidence":"traditional","note":"A traditional Ayurvedic practice. We did not find strong evidence that tulsi shortens colds.","safety":"Generally used as a food-level drink. Talk to a doctor before using concentrated tulsi supplements, especially in pregnancy."},{"practice":"Vitamin C, garlic or echinacea to beat a cold","evidence":"limited","note":"NHS notes little evidence that these prevent colds or help you get better faster.","safety":"Food amounts are fine. Supplements can interact with medicines."}]'::jsonb,'{"infant":"A baby under 3 months with a temperature of 38°C or more needs urgent medical advice.","child":"Children’s colds can last longer. Watch for breathing difficulty and poor feeding."}'::jsonb,null,'[{"id":"breathing","text":"Any difficulty breathing, or chest pain?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Breathing difficulty or chest pain needs urgent care."}]},{"id":"fever","text":"Is there a high fever, or does the person feel very unwell?","text_hi":"क्या तेज़ बुखार है या बहुत ज़्यादा तबीयत ख़राब लग रही है?","options":[{"label":"No, feeling mostly okay","value":"no"},{"label":"Yes, high fever or feeling very unwell","value":"yes","escalate":"consider_advice","reason":"A high fever or feeling very unwell is a reason to speak to a doctor."}]}]'::jsonb,null,'self_care','[{"title":"Common cold","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/common-cold/","supports":"Rest, fluids; do not let children breathe steam from a bowl (scald risk); no honey under 12 months."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['cold','common cold','runny nose','blocked nose','sneezing','stuffy nose','zukam','jukam','sardi','sardi zukam','naak beh rahi','naak band','chheenk','nazla','सर्दी','ज़ुकाम','जुकाम','नाक बंद','छींक']::text[]);
