insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-mild-headache','Mild headache','हल्का सिरदर्द','discomfort','Mild headache','A dull or tight headache, often from stress, a skipped meal, too little water or long screen time.',array['adult','child','older_adult']::text[],'All ages','Drink water, rest, take a break from screens, eat regular meals, and try to relax. Most headaches go away on their own.','supported','NHS self-care advice for headaches: fluids, rest, relaxation, regular meals, less screen strain. Emergency warning signs are well established.','["Drink a glass or two of water.","Rest in a quiet, dim room for a while.","Take a break from screens and look into the distance.","Eat something if you have skipped a meal.","Try slow breathing or a short walk in fresh air.","A pharmacist can advise on suitable pain relief. Do not use painkillers on many days a month."]'::jsonb,'["Do not skip meals.","Do not sleep much more than usual.","Avoid alcohol.","Frequent painkiller use can itself cause headaches."]'::jsonb,'["Headaches that happen regularly","A headache that is not easing or is getting worse"]'::jsonb,'[]'::jsonb,'["Sudden, extremely painful headache (\"worst ever\")","Weakness or numbness in the face, arm or leg, or slurred speech","Headache after a head injury","Seizure (fit), confusion or drowsiness","Stiff neck with fever, or a rash that does not fade under a glass","Loss of vision"]'::jsonb,'["Headache with vision problems, or with vomiting","Headache triggered by coughing, sneezing, bending or exercise","A child’s headache that is getting worse or wakes them at night","Jaw pain when eating or a tender scalp (especially over 50)"]'::jsonb,'[{"practice":"Rubbing balm or peppermint oil on the temples","evidence":"limited","note":"Some small studies suggest peppermint oil on the forehead may ease tension headaches. Evidence is limited.","safety":"Keep away from eyes. Do not use strong balms or peppermint oil on young children’s faces."}]'::jsonb,null,null,'[{"id":"sudden","text":"Did it start suddenly and very severely, or come with weakness, confusion, a stiff neck or trouble speaking?","text_hi":"क्या दर्द अचानक बहुत तेज़ शुरू हुआ, या कमज़ोरी, उलझन, गर्दन अकड़ना या बोलने में दिक्कत है?","options":[{"label":"No, it is a dull, ordinary headache","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"These can be signs of a serious problem. Call 112 or go to emergency now."}]},{"id":"injury","text":"Any head injury recently?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"A headache after a head injury needs urgent assessment."}]}]'::jsonb,null,'self_care','[{"title":"Headaches","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/headaches/","supports":"Water, rest, avoiding screen strain; emergency headache warning signs."},{"title":"Peppermint Oil: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/peppermint-oil","supports":"Only a small amount of research on peppermint oil; promoted for headaches among other uses."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['headache','head ache','head pain','migraine','sir dard','sirdard','sar dard','sar mein dard','sir me dard','sir phat raha','सिरदर्द','सिर दर्द','सर दर्द']::text[]);
