insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-mild-nausea','Mild nausea','जी मिचलाना','discomfort','Feeling sick (mild nausea)','Feeling queasy or like you might vomit, without other serious symptoms.',array['adult','child','older_adult']::text[],'All ages','Get fresh air, take small sips of a cold drink, try ginger or peppermint tea, and eat small, plain meals. Nausea usually passes on its own.','supported','NHS self-care advice for nausea. Research on ginger for some types of nausea is promising but mixed (NCCIH).','["Get some fresh air.","Take small, regular sips of a cold drink.","Try ginger or peppermint tea, or ginger biscuits.","Eat smaller, more frequent plain meals.","Distract yourself with music or something to watch."]'::jsonb,'["Avoid strong-smelling, fried or greasy food.","Do not eat too quickly or lie down right after eating.","Avoid tight clothes around the waist."]'::jsonb,'["Vomiting that means you cannot keep fluids down","Signs of dehydration"]'::jsonb,'["If pregnant, speak to your doctor or midwife about nausea that is severe or stops you keeping fluids down."]'::jsonb,'["Nausea with chest pain, or pain spreading to the arm, back, neck or jaw","Shortness of breath","Vomiting blood or material that looks like coffee grounds","Severe tummy pain or a sudden severe headache","May have swallowed something poisonous"]'::jsonb,'["Not feeling better in a few days","Nausea keeps coming back"]'::jsonb,'[{"practice":"Adrak (ginger) for nausea","evidence":"limited","note":"NHS lists ginger as something that may help. NCCIH reports some evidence for certain types of nausea, but studies are mixed.","safety":"Can cause heartburn or tummy upset. Ask a doctor before taking ginger supplements if you are on blood thinners or pregnant."}]'::jsonb,null,null,'[{"id":"chest","text":"Any chest pain, shortness of breath, or pain spreading to the arm or jaw?","text_hi":"क्या सीने में दर्द, सांस फूलना, या दर्द बांह/जबड़े तक फैल रहा है?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Nausea with chest pain or breathlessness can be a heart attack. Call 112 now."}]},{"id":"poison","text":"Could they have swallowed something harmful (medicine, cleaner, chemical)?","options":[{"label":"No","value":"no"},{"label":"Yes or not sure","value":"yes","escalate":"urgent","reason":"Possible poisoning. Call 112 or the Poisons Information Centre (1800 116 117) now."}]}]'::jsonb,null,'self_care','[{"title":"Feeling sick (nausea)","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/feeling-sick-nausea/","supports":"Fresh air, sips of cold drinks, ginger or peppermint tea, small meals."},{"title":"Ginger: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ginger","supports":"Evidence on ginger for nausea; possible side effects."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['nausea','nauseous','queasy','feel sick','feel like vomiting','ji machal','ji michla','ji ghabra','ulti jaisa','ulti aa rahi','jee machla','जी मिचलाना','उल्टी जैसा','मतली']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-nausea','summary','Mild nausea. Feeling sick (mild nausea). Get fresh air, take small sips of a cold drink, try ginger or peppermint tea, and eat small, plain meals. Nausea usually passes on its own.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-nausea','problem','Feeling queasy or like you might vomit, without other serious symptoms.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-nausea','keywords','nausea nauseous queasy feel sick feel like vomiting ji machal ji michla ji ghabra ulti jaisa ulti aa rahi jee machla जी मिचलाना उल्टी जैसा मतली');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-indigestion','Acidity or indigestion','एसिडिटी / अपच','discomfort','Acidity, heartburn or indigestion','Burning in the chest, sour taste, bloating or feeling too full after eating.',array['adult','older_adult']::text[],'Adults','Eat smaller, more frequent meals, cut down on tea, coffee, alcohol and rich or spicy food, and avoid eating 3–4 hours before bed. A pharmacist can recommend antacids for occasional use.','supported','NHS self-care advice for indigestion and heartburn: meal timing, trigger foods, raising the head of the bed, pharmacist-recommended antacids.','["Eat smaller meals more often.","Cut down on tea, coffee, cola and alcohol.","Avoid rich, spicy or fatty foods that trigger it for you.","Do not eat in the 3–4 hours before bed.","Raise the head of the bed by 10–20 cm (with blocks under the legs, not extra pillows).","For occasional relief, a pharmacist can suggest an antacid."]'::jsonb,'["Do not take ibuprofen or aspirin unless prescribed. They can make it worse.","Do not stop any prescribed medicine without talking to your doctor.","Avoid tight clothes around the waist."]'::jsonb,'["Needing antacids most days","Symptoms after most meals"]'::jsonb,'[]'::jsonb,'["Chest pain that feels tight or heavy, or spreads to the arm, neck, jaw or back","Breathlessness or sweating with chest discomfort","Vomiting blood or black, tarry stools","Difficulty swallowing"]'::jsonb,'["Indigestion keeps coming back","Losing weight without trying","Severe pain","Frequent vomiting","Feeling a lump in the stomach"]'::jsonb,'[{"practice":"Ajwain (carom seeds) or saunf (fennel) after meals","evidence":"traditional","note":"Very common in Indian households for digestion. We did not find good-quality evidence confirming the benefit.","safety":"Food amounts are generally fine. Concentrated extracts and oils are not."},{"practice":"Cold milk for acidity","evidence":"traditional","note":"May feel soothing briefly, but milk can also trigger more acid later for some people.","safety":"Not harmful for most. Stop if it makes symptoms worse."}]'::jsonb,'{"older_adult":"New indigestion in someone over 55, especially with weight loss or swallowing difficulty, should be checked by a doctor."}'::jsonb,null,'[{"id":"chest","text":"Is the chest pain tight or heavy, spreading to the arm, jaw or back, or with sweating or breathlessness?","text_hi":"क्या सीने में भारीपन/जकड़न है जो बांह, जबड़े या पीठ तक फैल रहा है, या पसीना/सांस फूलना?","options":[{"label":"No, it is a burning feeling after food","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"This could be a heart problem, not acidity. Call 112 now."}]},{"id":"blood","text":"Any vomiting blood or black stools?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"This can be internal bleeding. Get emergency care."}]}]'::jsonb,null,'self_care','[{"title":"Indigestion","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/indigestion/","supports":"Cutting down tea/coffee, not eating 3–4 hours before bed; warning symptoms."},{"title":"Heartburn and acid reflux","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/heartburn-and-acid-reflux/","supports":"Smaller meals, trigger foods, raising the head of the bed."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['acidity','acid','heartburn','indigestion','gas','bloating','burning chest after food','acid reflux','khatti dakar','pet mein jalan','seene mein jalan','apach','badhazmi','gas ban rahi','एसिडिटी','अपच','गैस','जलन','खट्टी डकार']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-indigestion','summary','Acidity or indigestion. Acidity, heartburn or indigestion. Eat smaller, more frequent meals, cut down on tea, coffee, alcohol and rich or spicy food, and avoid eating 3–4 hours before bed. A pharmacist can recommend antacids for occasional use.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-indigestion','problem','Burning in the chest, sour taste, bloating or feeling too full after eating.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-indigestion','keywords','acidity acid heartburn indigestion gas bloating burning chest after food acid reflux khatti dakar pet mein jalan seene mein jalan apach badhazmi gas ban rahi एसिडिटी अपच गैस जलन खट्टी डकार');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-constipation','Occasional constipation','कब्ज़','discomfort','Occasional constipation','Pooing less often than usual, or hard, dry stools that are difficult to pass.',array['adult','older_adult']::text[],'Adults (children have separate guidance)','Drink more fluids, gradually add fibre (fruit, vegetables, whole grains, oats), keep active, and do not delay when you feel the urge.','supported','NHS advice: diet, fluids, toilet routine and activity. A pharmacist can advise on short-term laxatives if these do not help.','["Drink plenty of water through the day.","Gradually increase fibre: fruit (e.g. apples, grapes, raisins), vegetables, dal, whole grains, oats.","Keep a regular time for the toilet and do not delay when you feel the urge.","Rest your feet on a low stool so your knees are above your hips.","A daily walk can help."]'::jsonb,'["Do not increase fibre suddenly without more water.","Do not use laxatives regularly without advice."]'::jsonb,'["No improvement after a few weeks of changes","Bloating and pain getting worse"]'::jsonb,'["If constipation started after a new medicine, ask the pharmacist or doctor."]'::jsonb,'["Blood in the stool or bleeding from the bottom","Severe tummy pain with vomiting and unable to pass wind","Unexplained weight loss"]'::jsonb,'["Constipation is not getting better with self-care","Often constipated","Tiredness and weight loss with it","Older adult with new confusion (constipation can be missed)"]'::jsonb,'[{"practice":"Isabgol (psyllium husk) with water","evidence":"limited","note":"Psyllium is a common fibre supplement. Fibre helps constipation; follow the pack directions.","safety":"Take with plenty of water. Separate from other medicines by a couple of hours. Ask a doctor if you have swallowing problems."},{"practice":"Triphala churna","evidence":"traditional","note":"A traditional Ayurvedic preparation used for bowels. Good-quality evidence is limited.","safety":"Some Ayurvedic products have been found to contain heavy metals (NCCIH). Not for pregnancy or children without medical advice."}]'::jsonb,'{"child":"This guide is written for adults. Children’s constipation should be discussed with a doctor or pharmacist."}'::jsonb,'[{"audience":"infant","reason":"Constipation in babies needs advice from a doctor or health worker.","escalate":"consider_advice"}]'::jsonb,'[{"id":"severe","text":"Any severe tummy pain with vomiting, or blood in the stool?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"These need prompt medical assessment."}]}]'::jsonb,null,'self_care','[{"title":"Constipation","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/constipation/","supports":"Fibre, fluids, toilet routine, activity."},{"title":"Ayurvedic Medicine: In Depth","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ayurvedic-medicine-in-depth","supports":"Some Ayurvedic preparations may contain toxic levels of lead, mercury or arsenic."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['constipation','constipated','poop','pooped','pooping','bowel','bowels','hard poo','no potty','hard stool','cannot poo','kabz','kabj','kabji','pet saaf nahi','pet saf nahi','potty nahi','latrine nahi','कब्ज़','कब्ज','पेट साफ़ नहीं']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-constipation','summary','Occasional constipation. Occasional constipation. Drink more fluids, gradually add fibre (fruit, vegetables, whole grains, oats), keep active, and do not delay when you feel the urge.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-constipation','problem','Pooing less often than usual, or hard, dry stools that are difficult to pass.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-constipation','keywords','constipation constipated poop pooped pooping bowel bowels hard poo no potty hard stool cannot poo kabz kabj kabji pet saaf nahi pet saf nahi potty nahi latrine nahi कब्ज़ कब्ज पेट साफ़ नहीं');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-mild-dehydration','Mild dehydration','पानी की कमी','discomfort','Mild dehydration','Thirst, dark yellow urine, dry mouth, headache or tiredness, often in heat or after loose motions.',array['adult','child','older_adult']::text[],'All ages (babies and older adults are at higher risk)','Drink fluids steadily, starting with small sips if you feel sick. If you have been vomiting or have diarrhoea, use an oral rehydration solution (ORS).','supported','NHS and WHO guidance: fluids and ORS replace water and salts. Babies, children and older adults are more at risk.','["Drink water regularly. Start with small sips if you feel sick.","If there is vomiting or diarrhoea, use ORS made up exactly as the packet says.","Rest in a cool place.","Keep breastfeeding or formula feeding babies as usual."]'::jsonb,'["Avoid alcohol and lots of caffeine.","Avoid fizzy drinks and fruit juice with diarrhoea.","Do not make ORS stronger or weaker than the packet says.","Do not dilute baby formula."]'::jsonb,'["Dark urine continuing","Peeing less, or fewer wet nappies"]'::jsonb,'["People told to limit fluids (e.g. for heart or kidney conditions) should follow their doctor’s advice."]'::jsonb,'["Confusion, very sleepy or hard to wake","Cold, blotchy, pale or blue-grey skin","Fast breathing or fast heartbeat","A baby with a sunken soft spot, few or no wet nappies, or no tears","Cannot keep any fluids down"]'::jsonb,'["Dizziness on standing that does not go away","Still dehydrated after using ORS","A child under 5 with signs of dehydration","Diarrhoea for more than 7 days or vomiting for more than 2 days"]'::jsonb,'[{"practice":"Nimbu-paani with a pinch of salt and sugar, nariyal paani, chaas","evidence":"limited","note":"These are good everyday fluids. For vomiting or diarrhoea, packaged ORS has the right balance of salts and sugar.","safety":"Home-made salt-sugar mixes can easily be too salty. Prefer ORS packets when someone is ill."}]'::jsonb,'{"infant":"Babies dehydrate quickly. Keep feeding and speak to a doctor if there are fewer wet nappies or they seem drowsy.","older_adult":"Older adults may not feel thirsty. Offer drinks regularly, especially in summer."}'::jsonb,'[{"audience":"infant","reason":"Babies can become seriously dehydrated quickly. Speak to a doctor.","escalate":"consider_advice"}]'::jsonb,'[{"id":"severe","text":"Any confusion, extreme sleepiness, cold or blotchy skin, or unable to keep fluids down?","text_hi":"क्या उलझन, बहुत ज़्यादा नींद, ठंडी/धब्बेदार त्वचा, या पानी भी न टिकना?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"These are signs of severe dehydration. Get emergency care."}]}]'::jsonb,null,'self_care','[{"title":"Dehydration","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/dehydration/","supports":"Symptoms, sipping fluids, oral rehydration solution, emergency signs."},{"title":"Diarrhoeal disease (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/diarrhoeal-disease","supports":"Oral rehydration solution for fluid loss; safe water and hygiene."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['dehydration','dehydrated','thirsty','dark urine','dry mouth','ors','paani ki kami','pani ki kami','pyaas','पानी की कमी','प्यास','डिहाइड्रेशन']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-dehydration','summary','Mild dehydration. Mild dehydration. Drink fluids steadily, starting with small sips if you feel sick. If you have been vomiting or have diarrhoea, use an oral rehydration solution (ORS).');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-dehydration','problem','Thirst, dark yellow urine, dry mouth, headache or tiredness, often in heat or after loose motions.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-mild-dehydration','keywords','dehydration dehydrated thirsty dark urine dry mouth ors paani ki kami pani ki kami pyaas पानी की कमी प्यास डिहाइड्रेशन');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-loose-motions','Loose motions or stomach upset','दस्त / पेट ख़राब','discomfort','Loose motions or mild food poisoning','Diarrhoea, with or without some vomiting or tummy cramps, often after eating outside or spoiled food.',array['adult','child','older_adult']::text[],'All ages (babies and older adults dehydrate faster)','The most important thing is to replace fluids: sip water and use ORS. Rest, and eat light food when you feel able. Most cases get better within a few days to a week.','supported','NHS food poisoning guidance and WHO diarrhoeal disease guidance: fluids and oral rehydration solution are the core treatment; watch for dehydration and warning signs.','["Drink plenty of fluids. Take small, frequent sips if you feel sick.","Use ORS made up exactly as the packet says, especially after each loose motion.","Keep breastfeeding or formula feeding babies. Give small feeds more often.","Eat when you feel able. Plain, light food like khichdi, curd-rice, banana or toast is easier to manage. Avoid fatty or spicy food.","Wash hands with soap after the toilet and before handling food, to protect others."]'::jsonb,'["Fruit juice and fizzy drinks: they can make diarrhoea worse.","Anti-diarrhoea medicines for children under 12.","Aspirin for children under 16.","Diluting baby formula.","Antibiotics without a doctor: most loose motions do not need them."]'::jsonb,'["Signs of dehydration: dark urine, peeing less, dizziness, dry mouth","Symptoms lasting more than a few days"]'::jsonb,'[]'::jsonb,'["Blood in stool or vomit, or vomit that looks like coffee grounds","Cannot keep any fluids down","Signs of severe dehydration: confusion, very sleepy, cold or blotchy skin","Sudden severe tummy pain","A baby under 12 months who is unwell, or stops feeding"]'::jsonb,'["Diarrhoea for more than 7 days, or vomiting for more than 2 days","Still dehydrated after using ORS","A child under 5 with signs of dehydration","Older adult, weakened immune system, or long-term health condition"]'::jsonb,'[{"practice":"Chaas, nariyal paani, khichdi and dahi during loose motions","evidence":"limited","note":"Light, familiar foods and fluids are sensible. They do not replace ORS when there is a lot of fluid loss.","safety":"Make sure buttermilk and curd are fresh. Use safe drinking water."},{"practice":"Stopping all food and water to “rest the stomach”","evidence":"not_recommended","note":"A common instinct, but fluids are the most important part of recovery.","safety":"Stopping fluids increases the risk of dehydration, especially in children."}]'::jsonb,'{"child":"Children dehydrate faster. Offer ORS often. Get help if they have fewer wet nappies or seem drowsy.","infant":"Babies can become seriously dehydrated quickly. Keep feeding and speak to a doctor today.","older_adult":"Older adults dehydrate more easily and may not feel thirsty. Offer fluids regularly."}'::jsonb,'[{"audience":"infant","reason":"Diarrhoea or vomiting in a baby under 12 months needs advice from a doctor today.","escalate":"consider_advice"}]'::jsonb,'[{"id":"blood","text":"Any blood in the stool or vomit, or severe tummy pain?","text_hi":"क्या मल या उल्टी में खून है, या पेट में बहुत तेज़ दर्द?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Blood or severe tummy pain needs urgent medical care."}]},{"id":"fluids","text":"Can they keep fluids down?","text_hi":"क्या पानी/ORS पेट में टिक रहा है?","options":[{"label":"Yes, mostly","value":"yes"},{"label":"No, vomiting everything","value":"no","escalate":"urgent","reason":"Not keeping any fluids down can quickly cause dangerous dehydration. Get medical help now."}]}]'::jsonb,null,'self_care','[{"title":"Food poisoning","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/food-poisoning/","supports":"Fluids and emergency signs after eating spoiled food."},{"title":"Diarrhoeal disease (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/diarrhoeal-disease","supports":"Oral rehydration solution for fluid loss; safe water and hygiene."},{"title":"Dehydration","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/dehydration/","supports":"Symptoms, sipping fluids, oral rehydration solution, emergency signs."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['loose motion','loose motions','diarrhoea','diarrhea','food poisoning','stomach upset','upset stomach','tummy upset','vomiting and diarrhoea','dast','dast lag gaye','pet kharab','pet kharaab','pet kharab hai','pet mein marod','marod','ulti dast','bahar ka khana','दस्त','पेट ख़राब','पेट खराब','मरोड़']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-loose-motions','summary','Loose motions or stomach upset. Loose motions or mild food poisoning. The most important thing is to replace fluids: sip water and use ORS. Rest, and eat light food when you feel able. Most cases get better within a few days to a week.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-loose-motions','problem','Diarrhoea, with or without some vomiting or tummy cramps, often after eating outside or spoiled food.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-loose-motions','keywords','loose motion loose motions diarrhoea diarrhea food poisoning stomach upset upset stomach tummy upset vomiting and diarrhoea dast dast lag gaye pet kharab pet kharaab pet kharab hai pet mein marod marod ulti dast bahar ka khana दस्त पेट ख़राब पेट खराब मरोड़');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-motion-sickness','Motion sickness','सफ़र में जी मिचलाना','discomfort','Motion sickness while travelling','Feeling dizzy or sick in a car, bus, boat or on hill roads.',array['adult','child','older_adult']::text[],'All ages','Sit in the front or where motion is least, look at a fixed point on the horizon, get fresh air, and avoid reading or screens. Ginger may help.','supported','NHS advice for motion sickness. Ginger is listed as something to try, with mixed evidence.','["Sit in the front seat of a car, or the middle of a boat.","Look straight ahead at a fixed point, like the horizon.","Open a window for fresh air.","Close your eyes and breathe slowly.","Break long journeys for air, water and a short walk.","Distract children with talking, music or songs.","A pharmacist can suggest travel-sickness medicines suitable for your age."]'::jsonb,'["Do not read, watch videos or use phones.","Avoid heavy, spicy meals or alcohol before or during travel."]'::jsonb,'["Vomiting that continues after the journey"]'::jsonb,'[]'::jsonb,'["Symptoms continue long after travel stops","Severe headache, confusion or weakness"]'::jsonb,'["Motion sickness is severe or stops you travelling","Symptoms happen without travel"]'::jsonb,'[{"practice":"Sucking on lemon, saunf, or a ginger candy on hill journeys","evidence":"traditional","note":"Ginger has some supporting evidence. Lemon and saunf are traditional with little research.","safety":"Fine for most adults. Avoid hard sweets for small children (choking)."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Motion sickness","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/motion-sickness/","supports":"Looking at the horizon, fresh air, not reading, ginger."},{"title":"Ginger: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ginger","supports":"Evidence on ginger for nausea; possible side effects."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['motion sickness','travel sickness','car sickness','car sick','sea sickness','vomiting in car','bus mein ulti','gaadi mein ulti','safar mein ulti','pahad','ghat road','यात्रा','सफ़र में उल्टी','गाड़ी में उल्टी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-motion-sickness','summary','Motion sickness. Motion sickness while travelling. Sit in the front or where motion is least, look at a fixed point on the horizon, get fresh air, and avoid reading or screens. Ginger may help.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-motion-sickness','problem','Feeling dizzy or sick in a car, bus, boat or on hill roads.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-motion-sickness','keywords','motion sickness travel sickness car sickness car sick sea sickness vomiting in car bus mein ulti gaadi mein ulti safar mein ulti pahad ghat road यात्रा सफ़र में उल्टी गाड़ी में उल्टी');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('dc-fatigue','Everyday tiredness','थकान','discomfort','Everyday tiredness','Feeling tired or low on energy for a few days, often from poor sleep, stress or routine changes.',array['adult','older_adult']::text[],'Adults','Aim for a regular sleep schedule (6–9 hours), eat well, stay active, and cut back on caffeine and screens late in the day. See a doctor if tiredness lasts weeks without a clear reason.','supported','NHS guidance on tiredness: sleep routine, diet, activity, and seeing a GP if fatigue is unexplained or lasting.','["Go to bed and get up at similar times each day.","Relax for a couple of hours before bed. Keep the room dark, quiet and not too warm.","Eat regular balanced meals.","Get some daylight and movement every day.","Avoid screens in the hour before sleep, and caffeine or heavy meals late in the evening."]'::jsonb,'["Do not rely on energy drinks or extra tea/coffee.","Avoid alcohol to help you sleep."]'::jsonb,'["Tiredness lasting more than a few weeks","Low mood, loss of interest, or weight changes"]'::jsonb,'[]'::jsonb,'["Breathlessness, chest pain, or fainting with tiredness","Very thirsty and peeing a lot","Thoughts of self-harm"]'::jsonb,'["Tired for a few weeks and you do not know why","It affects daily life","Loud snoring with gasping or choking at night","Other symptoms like weight loss or mood changes"]'::jsonb,'[{"practice":"Ashwagandha for energy and stress","evidence":"limited","note":"Some studies look at ashwagandha for stress and sleep. Evidence is limited and products vary in quality.","safety":"Rare cases of liver injury have been linked to supplements. Avoid in pregnancy and breastfeeding. Speak to a doctor if you take other medicines or have thyroid conditions."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Tiredness and fatigue","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/tiredness-and-fatigue/","supports":"Sleep routine, activity, when tiredness needs a GP."},{"title":"Ashwagandha: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ashwagandha","supports":"Rare cases of liver injury linked to supplements; avoid in pregnancy and breastfeeding."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['tired','tiredness','fatigue','no energy','exhausted','weakness','thakan','thakaan','kamzori','kamjori','neend puri nahi','susti','थकान','कमज़ोरी','सुस्ती']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-fatigue','summary','Everyday tiredness. Everyday tiredness. Aim for a regular sleep schedule (6–9 hours), eat well, stay active, and cut back on caffeine and screens late in the day. See a doctor if tiredness lasts weeks without a clear reason.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-fatigue','problem','Feeling tired or low on energy for a few days, often from poor sleep, stress or routine changes.');
insert into public.knowledge_chunks (item_id,kind,content) values ('dc-fatigue','keywords','tired tiredness fatigue no energy exhausted weakness thakan thakaan kamzori kamjori neend puri nahi susti थकान कमज़ोरी सुस्ती');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-toothpaste-burn','Toothpaste on a burn','जले पर टूथपेस्ट','traditional','Myth check: toothpaste on a burn','A very common household tip: put toothpaste on a burn to "cool" it.',array['adult','child','older_adult','infant']::text[],'All ages','Skip the toothpaste. Hold the burn under cool running water for 20 minutes, then cover it loosely with cling film or a clean non-fluffy cloth.','not_recommended','Toothpaste feels cool because of mint, but it does not cool the burn itself. NHS guidance says not to put creams, oils or butter on burns; toothpaste falls in the same category of substances that can trap heat and irritate damaged skin.','["Cool the burn under cool running water for 20 minutes.","Remove rings, bangles or clothing near the burn (unless stuck).","Cover loosely with cling film or a clean, non-fluffy cloth.","Get medical help for large, deep, electrical or chemical burns, or burns on the face, hands, feet or genitals."]'::jsonb,'["Toothpaste, butter, ghee, oil, or ice on burns.","Bursting blisters."]'::jsonb,'["Signs of infection over the following days"]'::jsonb,'[]'::jsonb,'["Burn larger than the person’s palm","Burn on face, hands, feet, genitals","Electrical or chemical burn","Any burn on a baby"]'::jsonb,'["Any of the red flags","Not sure how serious it is"]'::jsonb,'[{"practice":"Toothpaste on a burn","evidence":"not_recommended","note":"The mint gives a cooling feeling, which is why this tip spread. It does not treat the burn.","safety":"Can irritate the skin, raise infection risk and make the burn harder for a doctor to assess."}]'::jsonb,null,null,null,'{"claim":"Toothpaste on a burn helps it heal.","verdict":"Not recommended. Use cool running water for 20 minutes instead."}'::jsonb,'self_care','[{"title":"Burns and scalds","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/burns-and-scalds/","supports":"Cool running water for 20 minutes; no creams, oils or butter; when to go to A&E."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['toothpaste','toothpaste burn','toothpaste on burn','colgate','paste lagao','jale par toothpaste','jale par paste','टूथपेस्ट','पेस्ट']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-toothpaste-burn','summary','Toothpaste on a burn. Myth check: toothpaste on a burn. Skip the toothpaste. Hold the burn under cool running water for 20 minutes, then cover it loosely with cling film or a clean non-fluffy cloth.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-toothpaste-burn','problem','A very common household tip: put toothpaste on a burn to "cool" it.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-toothpaste-burn','keywords','toothpaste toothpaste burn toothpaste on burn colgate paste lagao jale par toothpaste jale par paste टूथपेस्ट पेस्ट');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-toothpaste-burn','myth','Toothpaste on a burn helps it heal. Not recommended. Use cool running water for 20 minutes instead.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-honey-newborn','Honey or ghutti for newborns','नवजात को शहद या घुट्टी','traditional','Myth check: honey for babies under 1','In many families a newborn is given honey (sometimes as janam ghutti) as a first taste or for cough.',array['infant']::text[],'Babies under 12 months','Do not give honey in any form to a baby under 12 months, including a tiny taste on the tongue. For babies, breast milk or formula is all they need until solids are started.','not_recommended','Honey can carry bacteria that cause infant botulism, a rare but serious illness. The NHS, MedlinePlus and the American Academy of Pediatrics all advise no honey before 12 months.','["Keep honey away from babies under 12 months, including for rituals like the first taste.","A ritual can be honoured in a safe way: touching the lips with breast milk, or a symbolic gesture without feeding.","For a baby’s cough or cold, speak to a doctor or health worker."]'::jsonb,'["Honey, honey-based ghutti or any home \"ghutti\" mix for babies under 1.","Sugar water, gripe water or other liquids for newborns unless a doctor advises."]'::jsonb,'["After any honey: constipation, weak cry, poor feeding, floppiness, drooping eyelids"]'::jsonb,'[]'::jsonb,'["A baby who is floppy, has a weak cry, trouble feeding or swallowing, or drooping eyelids"]'::jsonb,'["A baby under 1 was given honey and seems unwell in any way: see a doctor promptly"]'::jsonb,'[{"practice":"Shahad / janam ghutti for newborns","evidence":"not_recommended","note":"Deeply rooted in tradition and given with love. The risk is real: honey can cause infant botulism.","safety":"Wait until after the first birthday for honey."}]'::jsonb,null,null,null,'{"claim":"A little honey is good for a newborn.","verdict":"Not recommended. No honey before 12 months."}'::jsonb,'consider_advice','[{"title":"Infant botulism","publisher":"MedlinePlus (US National Library of Medicine)","url":"https://medlineplus.gov/ency/article/001384.htm","supports":"Honey should not be given to infants under 12 months."},{"title":"Botulism","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/botulism/","supports":"Infant botulism can be caused by honey."},{"title":"Coughs and Colds: Medicines or Home Remedies?","publisher":"HealthyChildren.org (American Academy of Pediatrics)","url":"https://www.healthychildren.org/English/health-issues/conditions/chest-lungs/Pages/Coughs-and-Colds-Medicines-or-Home-Remedies.aspx","supports":"No honey under 1 year; honey may help cough in children aged 1 and older."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['honey baby','honey newborn','honey infant','ghutti','janam ghutti','janm ghutti','shahad bachche','shahad baby','navjaat','newborn','शहद','घुट्टी','नवजात']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-honey-newborn','summary','Honey or ghutti for newborns. Myth check: honey for babies under 1. Do not give honey in any form to a baby under 12 months, including a tiny taste on the tongue. For babies, breast milk or formula is all they need until solids are started.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-honey-newborn','problem','In many families a newborn is given honey (sometimes as janam ghutti) as a first taste or for cough.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-honey-newborn','keywords','honey baby honey newborn honey infant ghutti janam ghutti janm ghutti shahad bachche shahad baby navjaat newborn शहद घुट्टी नवजात');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-honey-newborn','myth','A little honey is good for a newborn. Not recommended. No honey before 12 months.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-kajal-baby','Kajal or surma for babies','बच्चे की आँखों में काजल','traditional','Myth check: kajal / surma on a baby','Applying kajal or surma to a baby’s eyes, believed to make eyes bigger, stronger or ward off nazar.',array['infant','child']::text[],'Babies and young children','Avoid putting kajal, kohl or surma in or around a baby’s eyes. There is no evidence it strengthens or enlarges eyes, and some traditional kohl products contain lead.','not_recommended','The WHO lists some traditional cosmetics as a source of lead exposure, and notes young children are particularly vulnerable to lead. Rubbing eyes with fingers or products can also cause infection.','["Keep a baby’s eyes clean with cotton wool and clean boiled-and-cooled water, one piece per eye.","If a family ritual matters, a small dot on the forehead, behind the ear, or on the foot avoids the eye itself. Check the product is not lead-based.","See a doctor for sticky, red or watering eyes."]'::jsonb,'["Kajal, surma or kohl inside or along a baby’s eyelids.","Home-made kajal of unknown content."]'::jsonb,'["Red, sticky or swollen eyes","Constant watering"]'::jsonb,'[]'::jsonb,'["Red, swollen eyelids with fever","A baby who seems unusually drowsy or irritable (lead exposure can cause this)"]'::jsonb,'["Eye redness, discharge or swelling","Worried about lead exposure from cosmetics or home remedies: ask a doctor about testing"]'::jsonb,'[{"practice":"Kajal / surma on babies","evidence":"not_recommended","note":"Traditionally used for beauty and protection from nazar. It does not change eye size or strength.","safety":"Some products contain lead, and applying anything to a baby’s eye can introduce infection."}]'::jsonb,null,null,null,'{"claim":"Kajal makes a baby’s eyes bigger and stronger.","verdict":"Not recommended. No proven benefit, and some kajal contains lead."}'::jsonb,'self_care','[{"title":"Lead poisoning (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/lead-poisoning-and-health","supports":"Some traditional cosmetics and medicines contain lead; young children are especially vulnerable."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['kajal','kaajal','kajal lagana','kajal for baby','surma','kohl','kajal baby','baby eyes kajal','nazar','aankh mein kajal','काजल','सुरमा']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kajal-baby','summary','Kajal or surma for babies. Myth check: kajal / surma on a baby. Avoid putting kajal, kohl or surma in or around a baby’s eyes. There is no evidence it strengthens or enlarges eyes, and some traditional kohl products contain lead.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kajal-baby','problem','Applying kajal or surma to a baby’s eyes, believed to make eyes bigger, stronger or ward off nazar.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kajal-baby','keywords','kajal kaajal kajal lagana kajal for baby surma kohl kajal baby baby eyes kajal nazar aankh mein kajal काजल सुरमा');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kajal-baby','myth','Kajal makes a baby’s eyes bigger and stronger. Not recommended. No proven benefit, and some kajal contains lead.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-haldi-doodh','Haldi doodh (turmeric milk)','हल्दी वाला दूध','traditional','Traditional practice: haldi doodh','Warm turmeric milk given for colds, coughs, body ache or "immunity".',array['adult','child','older_adult']::text[],'Children and adults (not a replacement for care in babies)','Haldi doodh is a comforting warm drink and generally safe in food amounts. It is not a proven treatment for infections or a way to "boost immunity".','traditional','NCCIH says turmeric research is hard to compare and not conclusive for most uses. Some concentrated curcumin products (especially with black pepper extract) have been linked to liver harm.','["Enjoy it as a warm drink if it comforts you.","Serve warm, not hot, to children.","Keep to kitchen amounts of turmeric."]'::jsonb,'["Relying on it instead of seeing a doctor for fever, breathing difficulty or a long illness.","High-dose turmeric/curcumin supplements without medical advice."]'::jsonb,'["Symptoms not improving: follow the guide for your actual symptom"]'::jsonb,'["People on blood thinners, or with gallbladder problems, should ask a doctor before turmeric supplements."]'::jsonb,'[]'::jsonb,'["The illness it is being used for is severe, getting worse, or lasting"]'::jsonb,'[{"practice":"Haldi doodh for colds and immunity","evidence":"traditional","note":"Long tradition in Indian homes. Evidence that it treats colds or boosts immunity is not established.","safety":"Safe as a food drink for most. Supplements are different."}]'::jsonb,null,null,null,'{"claim":"Haldi doodh cures colds and boosts immunity.","verdict":"Traditional practice. Comforting, but not a proven treatment."}'::jsonb,'self_care','[{"title":"Turmeric: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/turmeric","supports":"Turmeric evidence is mixed and hard to compare; some curcumin products may harm the liver."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['haldi doodh','haldi wala doodh','turmeric milk','golden milk','haldi milk','immunity','हल्दी दूध','हल्दी वाला दूध']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-doodh','summary','Haldi doodh (turmeric milk). Traditional practice: haldi doodh. Haldi doodh is a comforting warm drink and generally safe in food amounts. It is not a proven treatment for infections or a way to "boost immunity".');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-doodh','problem','Warm turmeric milk given for colds, coughs, body ache or "immunity".');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-doodh','keywords','haldi doodh haldi wala doodh turmeric milk golden milk haldi milk immunity हल्दी दूध हल्दी वाला दूध');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-doodh','myth','Haldi doodh cures colds and boosts immunity. Traditional practice. Comforting, but not a proven treatment.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-kadha','Kadha (herbal decoction)','काढ़ा','traditional','Traditional practice: kadha for cough and cold','A warm decoction of tulsi, ginger, black pepper, cinnamon, cloves and sometimes honey or jaggery.',array['adult','older_adult','child']::text[],'Adults; small mild amounts for older children','A mild kadha can be a soothing warm drink. Warm fluids and honey may ease throat discomfort. Strong or frequent kadha can upset the stomach and is not a treatment for infections.','traditional','Warm fluids are part of standard cold self-care. Evidence for specific kadha herbs is limited; ginger has some evidence for nausea (NCCIH), not for colds.','["Keep it mild: food amounts of spices, well diluted.","Drink warm, not scalding.","Continue normal cold self-care: rest and fluids."]'::jsonb,'["Very strong kadha many times a day: it can cause acidity, mouth ulcers or stomach upset.","Honey in kadha for babies under 1 year.","Giving kadha to babies."]'::jsonb,'["Acidity or burning after kadha: reduce or stop"]'::jsonb,'["People on blood thinners or diabetes medicines should check with a doctor before large amounts of herbal drinks."]'::jsonb,'[]'::jsonb,'["Cold or cough is severe, getting worse, or lasting more than 3 weeks"]'::jsonb,'[{"practice":"Kadha for cold and cough","evidence":"traditional","note":"Widely used, especially since 2020. Comforting as a warm drink. Little evidence that it treats or prevents infection.","safety":"Keep it mild. Too much can irritate the stomach."}]'::jsonb,null,null,null,'{"claim":"Kadha treats and prevents infections.","verdict":"Traditional practice. Soothing as a warm drink, not a proven treatment."}'::jsonb,'self_care','[{"title":"Common cold","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/common-cold/","supports":"Rest, fluids; do not let children breathe steam from a bowl (scald risk); no honey under 12 months."},{"title":"Ginger: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ginger","supports":"Evidence on ginger for nausea; possible side effects."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['kadha','kaadha','kadhaa','decoction','herbal tea','tulsi','tulsi kadha','kaali mirch','काढ़ा','तुलसी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kadha','summary','Kadha (herbal decoction). Traditional practice: kadha for cough and cold. A mild kadha can be a soothing warm drink. Warm fluids and honey may ease throat discomfort. Strong or frequent kadha can upset the stomach and is not a treatment for infections.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kadha','problem','A warm decoction of tulsi, ginger, black pepper, cinnamon, cloves and sometimes honey or jaggery.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kadha','keywords','kadha kaadha kadhaa decoction herbal tea tulsi tulsi kadha kaali mirch काढ़ा तुलसी');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-kadha','myth','Kadha treats and prevents infections. Traditional practice. Soothing as a warm drink, not a proven treatment.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-steam-bowl','Steam from a bowl (bhaap lena)','भाप लेना','traditional','Traditional practice: steam inhalation','Breathing in steam from a bowl of hot water, sometimes with Vicks or ajwain, for a blocked nose.',array['adult','older_adult','child']::text[],'Adults only for bowl steam','For adults, steam from a hot shower may ease a blocked nose. Children should never breathe steam from a bowl of hot water because of the risk of serious scalds.','limited','NHS suggests breathing steam in a steamy bathroom to ease a blocked nose, and specifically warns not to let children breathe steam from a bowl because of scalding.','["Adults: sit in the bathroom with a hot shower running for a few minutes.","If using a bowl (adults only): place it on a stable table, keep your face at a safe distance, and never move the bowl while it is hot.","For children: a steamy bathroom with an adult present, not a bowl."]'::jsonb,'["Bowl steam for children.","Boiling water on a bed, lap or unstable surface.","Putting balms or oils on children’s faces or into steam for babies."]'::jsonb,'["Any redness or pain on the face or hands after steam: treat as a burn"]'::jsonb,'[]'::jsonb,'["A scald from steam or hot water: cool it under running water for 20 minutes and get help if it is large or on a child"]'::jsonb,'["A child is scalded","Blocked nose with breathing difficulty"]'::jsonb,'[{"practice":"Bhaap (steam) from a bowl for cold","evidence":"limited","note":"May ease a blocked nose for some adults. Does not cure the cold.","safety":"A leading cause of scalds in children. Adults only."}]'::jsonb,null,'[{"audience":"infant","reason":"Never use bowl steam around babies. For a baby’s blocked nose, speak to a doctor or pharmacist.","escalate":"consider_advice"}]'::jsonb,null,'{"claim":"Bhaap is safe for the whole family.","verdict":"Limited evidence for adults. Not safe for children from a bowl."}'::jsonb,'self_care','[{"title":"Common cold","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/common-cold/","supports":"Rest, fluids; do not let children breathe steam from a bowl (scald risk); no honey under 12 months."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['steam','steam inhalation','bhaap','bhap','bhaap lena','vapour','vicks steam','ajwain steam','भाप']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-steam-bowl','summary','Steam from a bowl (bhaap lena). Traditional practice: steam inhalation. For adults, steam from a hot shower may ease a blocked nose. Children should never breathe steam from a bowl of hot water because of the risk of serious scalds.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-steam-bowl','problem','Breathing in steam from a bowl of hot water, sometimes with Vicks or ajwain, for a blocked nose.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-steam-bowl','keywords','steam steam inhalation bhaap bhap bhaap lena vapour vicks steam ajwain steam भाप');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-steam-bowl','myth','Bhaap is safe for the whole family. Limited evidence for adults. Not safe for children from a bowl.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-oil-in-ear','Warm oil or garlic oil in the ear','कान में तेल डालना','traditional','Traditional practice: oil in the ear','Putting warm mustard oil, garlic oil or other drops in the ear for earache or wax.',array['adult','child','older_adult']::text[],'All ages','Avoid putting home-made oils or objects into an aching ear. Most ear infections improve within about 3 days; pain relief and a pharmacist’s or doctor’s advice are the safer route.','not_recommended','NHS advice for ear infections: do not put anything inside your ear, and do not let water get in. There is no good evidence that home oils treat earache, and oil in an ear with a perforated eardrum can cause harm.','["Use pain relief suitable for the person’s age (ask a pharmacist).","Wipe away any discharge from the outer ear with cotton wool.","Keep water out of the ear.","See a pharmacist or doctor if earache lasts more than 3 days or there is fever."]'::jsonb,'["Hot oil, garlic oil or home drops in the ear.","Cotton buds, hairpins or matchsticks in the ear.","Swimming while the ear hurts."]'::jsonb,'["Discharge from the ear","Hearing change","Fever"]'::jsonb,'["Never put anything in an ear that has discharge or a known perforated eardrum."]'::jsonb,'["Swelling or redness behind the ear","Severe pain with high fever or confusion","Earache after a head injury or with blood from the ear"]'::jsonb,'["Earache lasting more than 3 days","Baby under 12 months with suspected ear infection","Discharge, fever or feeling unwell"]'::jsonb,'[{"practice":"Sarson / lehsun ka tel in the ear","evidence":"not_recommended","note":"A common home remedy. No good evidence it helps, and it can hide or worsen problems.","safety":"Hot oil can burn the ear canal. Oil through a perforated eardrum can cause harm."}]'::jsonb,null,null,null,'{"claim":"Warm mustard or garlic oil cures earache.","verdict":"Not recommended. Do not put things in an aching ear."}'::jsonb,'self_care','[{"title":"Ear infections","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/ear-infections/","supports":"Do not put anything inside your ear; most ear infections improve within 3 days; when to see a GP."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['ear oil','oil in ear','earache','ear pain','kaan','kaan dard','kan dard','kaan mein tel','kaan me tel','garlic oil ear','lehsun tel','sarson tel kaan','कान','कान दर्द','कान में तेल']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-oil-in-ear','summary','Warm oil or garlic oil in the ear. Traditional practice: oil in the ear. Avoid putting home-made oils or objects into an aching ear. Most ear infections improve within about 3 days; pain relief and a pharmacist’s or doctor’s advice are the safer route.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-oil-in-ear','problem','Putting warm mustard oil, garlic oil or other drops in the ear for earache or wax.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-oil-in-ear','keywords','ear oil oil in ear earache ear pain kaan kaan dard kan dard kaan mein tel kaan me tel garlic oil ear lehsun tel sarson tel kaan कान कान दर्द कान में तेल');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-oil-in-ear','myth','Warm mustard or garlic oil cures earache. Not recommended. Do not put things in an aching ear.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-haldi-wound','Haldi (turmeric) on a wound','घाव पर हल्दी','traditional','Traditional practice: turmeric on a cut','Pressing turmeric powder into a fresh cut to stop bleeding and "disinfect" it.',array['adult','child','older_adult']::text[],'All ages','Stop bleeding with firm pressure, rinse with clean water, and cover with a clean dressing. Turmeric is not needed and not proven to help wounds heal.','traditional','Standard NHS first aid is pressure, rinsing with clean water, and a clean dressing. NCCIH notes that turmeric research is inconclusive for most uses.','["Press with a clean cloth until the bleeding stops.","Rinse under clean running water.","Cover with a clean plaster or dressing."]'::jsonb,'["Packing powders (haldi, ash, coffee, chuna) into deep or dirty wounds."]'::jsonb,'["Redness, pus or swelling getting worse"]'::jsonb,'[]'::jsonb,'["Bleeding that does not stop with 10 minutes of pressure","Deep or gaping cut","Animal bite"]'::jsonb,'["Signs of infection","Deep, dirty or large wounds"]'::jsonb,'[{"practice":"Haldi on fresh cuts","evidence":"traditional","note":"Turmeric has been studied in the lab, but there is no good evidence that household haldi on a cut improves healing.","safety":"Kitchen powder is not sterile and can hide how the wound looks."}]'::jsonb,null,null,null,'{"claim":"Haldi is the best antiseptic for cuts.","verdict":"Traditional practice. Clean water and a clean dressing are the proven steps."}'::jsonb,'self_care','[{"title":"Cuts and grazes","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/cuts-and-grazes/","supports":"Stopping bleeding, cleaning and dressing small wounds; when to get help."},{"title":"Turmeric: Usefulness and Safety","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/turmeric","supports":"Turmeric evidence is mixed and hard to compare; some curcumin products may harm the liver."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['haldi on cut','turmeric on wound','turmeric cut','haldi lagao','haldi ghav','haldi chot','घाव पर हल्दी','हल्दी लगाओ']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-wound','summary','Haldi (turmeric) on a wound. Traditional practice: turmeric on a cut. Stop bleeding with firm pressure, rinse with clean water, and cover with a clean dressing. Turmeric is not needed and not proven to help wounds heal.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-wound','problem','Pressing turmeric powder into a fresh cut to stop bleeding and "disinfect" it.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-wound','keywords','haldi on cut turmeric on wound turmeric cut haldi lagao haldi ghav haldi chot घाव पर हल्दी हल्दी लगाओ');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-haldi-wound','myth','Haldi is the best antiseptic for cuts. Traditional practice. Clean water and a clean dressing are the proven steps.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-ayurvedic-products','Buying Ayurvedic churan, bhasma or tablets','आयुर्वेदिक चूर्ण / भस्म सुरक्षा','traditional','Safety check: Ayurvedic products','Taking Ayurvedic powders, bhasmas or tablets bought online or from unlicensed sellers.',array['adult','older_adult','child']::text[],'Adults (extra caution for children and pregnancy)','Ayurveda is a respected traditional system, but product quality varies. Some Ayurvedic preparations have been found to contain toxic levels of lead, mercury or arsenic. Use licensed products, tell your doctor what you take, and avoid them for children and in pregnancy unless a doctor advises.','limited','NCCIH reports a few studies suggesting benefit for some conditions, but notes safety concerns including heavy metals in some preparations.','["Buy only licensed products with a clear label, batch number and manufacturer.","Consult a qualified practitioner (BAMS) and tell your regular doctor too.","Never stop a prescribed medicine to switch to an herbal product without your doctor."]'::jsonb,'["Unlabelled powders or “secret formula” products.","Bhasmas (metal-based preparations) for children or in pregnancy without medical advice.","Combining several herbal products with regular medicines."]'::jsonb,'["Stomach pain, tiredness, tingling, or changes in behaviour in children after herbal products"]'::jsonb,'["Pregnancy, breastfeeding, children, and people with kidney or liver disease need medical advice first."]'::jsonb,'["Suspected poisoning after taking a product: call the Poisons Information Centre (1800 116 117)"]'::jsonb,'["Taking herbal products alongside prescription medicines","Any new symptoms after starting a product"]'::jsonb,'[{"practice":"Ayurvedic preparations for everyday complaints","evidence":"limited","note":"Some preparations have limited supporting studies. Quality and contents vary greatly between products.","safety":"Heavy-metal contamination has been found in some products."}]'::jsonb,null,null,null,'{"claim":"Natural means safe.","verdict":"Not always. Some products contain toxic metals. Buy licensed and tell your doctor."}'::jsonb,'consider_advice','[{"title":"Ayurvedic Medicine: In Depth","publisher":"NCCIH (US National Institutes of Health)","url":"https://www.nccih.nih.gov/health/ayurvedic-medicine-in-depth","supports":"Some Ayurvedic preparations may contain toxic levels of lead, mercury or arsenic."},{"title":"Lead poisoning (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/lead-poisoning-and-health","supports":"Some traditional cosmetics and medicines contain lead; young children are especially vulnerable."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['ayurvedic medicine','ayurveda','churan','churna','bhasma','jadi booti','herbal medicine','desi dawa','desi dawai','natural means safe','आयुर्वेद','चूर्ण','भस्म','जड़ी बूटी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-ayurvedic-products','summary','Buying Ayurvedic churan, bhasma or tablets. Safety check: Ayurvedic products. Ayurveda is a respected traditional system, but product quality varies. Some Ayurvedic preparations have been found to contain toxic levels of lead, mercury or arsenic. Use licensed products, tell your doctor what you take, and avoid them for children and in pregnancy unless a doctor advises.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-ayurvedic-products','problem','Taking Ayurvedic powders, bhasmas or tablets bought online or from unlicensed sellers.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-ayurvedic-products','keywords','ayurvedic medicine ayurveda churan churna bhasma jadi booti herbal medicine desi dawa desi dawai natural means safe आयुर्वेद चूर्ण भस्म जड़ी बूटी');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-ayurvedic-products','myth','Natural means safe. Not always. Some products contain toxic metals. Buy licensed and tell your doctor.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('tr-copper-water','Water stored in a copper vessel','तांबे के बर्तन का पानी','traditional','Traditional practice: tambe ka paani','Drinking water stored overnight in a copper (tamba) lota or bottle for health benefits.',array['adult','older_adult']::text[],'Adults','Drinking plain water from a clean copper vessel is a harmless tradition for most adults. Claims about major health benefits are not well established. Do not store acidic drinks (nimbu-paani, juices) in copper.','traditional','We could not find an authoritative public-health source to cite for specific benefits. This item is marked as needing expert review and a verified source.','["Clean the vessel regularly (e.g. with lemon and salt, then rinse well).","Store plain water only.","Drink normal amounts of water. More copper is not better."]'::jsonb,'["Storing lemon water, juice or other acidic drinks in copper.","Using old vessels with green or black deposits without cleaning."]'::jsonb,'["Metallic taste, stomach upset or nausea: stop and switch to another vessel"]'::jsonb,'["People with Wilson’s disease or liver disease should avoid extra copper."]'::jsonb,'[]'::jsonb,'["Ongoing nausea or tummy pain"]'::jsonb,'[{"practice":"Tambe ka paani every morning","evidence":"traditional","note":"Ayurvedic practice. Health claims have not been confirmed by good-quality studies.","safety":"Fine for plain water in a clean vessel."}]'::jsonb,null,null,null,'{"claim":"Copper water cures many diseases.","verdict":"Traditional practice. Harmless for most, but health claims are unproven."}'::jsonb,'self_care','[{"title":"Awaiting a verified source","publisher":"GharGyaan editorial draft","supports":"No authoritative source verified yet. Needs expert review before publication."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['copper','copper water','copper bottle','tamba','tambe ka paani','tambe ka pani','copper lota','तांबा','तांबे का पानी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-copper-water','summary','Water stored in a copper vessel. Traditional practice: tambe ka paani. Drinking plain water from a clean copper vessel is a harmless tradition for most adults. Claims about major health benefits are not well established. Do not store acidic drinks (nimbu-paani, juices) in copper.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-copper-water','problem','Drinking water stored overnight in a copper (tamba) lota or bottle for health benefits.');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-copper-water','keywords','copper copper water copper bottle tamba tambe ka paani tambe ka pani copper lota तांबा तांबे का पानी');
insert into public.knowledge_chunks (item_id,kind,content) values ('tr-copper-water','myth','Copper water cures many diseases. Traditional practice. Harmless for most, but health claims are unproven.');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-haldi-stain','Haldi (turmeric) stain on clothes','कपड़े पर हल्दी का दाग','household','Turmeric / curry stain on fabric','Yellow haldi or curry stain on clothes, a kurta, or a tablecloth.',array['adult']::text[],'Adults (keep cleaning products away from children)','Act fast: scrape off excess, rinse from the back with cold water, work in liquid detergent, then wash. Drying in sunlight often fades what is left.','limited','Common laundry practice. Results depend on fabric and how old the stain is. Always test on a hidden area first.','["Scrape off any extra curry with a spoon. Do not rub it in.","Rinse from the back of the fabric under cold running water.","Work a little liquid detergent or dishwashing liquid into the stain. Leave for 10–15 minutes.","Wash as usual, in cold or warm water as the label allows.","Dry in direct sunlight: turmeric colour often fades in sun.","Check before machine drying or ironing; heat can set the stain."]'::jsonb,'["Hot water first (can set the stain).","Chlorine bleach on coloured, silk or wool fabrics.","Never mix bleach with ammonia, acids (vinegar, lemon, toilet cleaners) or other cleaners. It can release toxic gas."]'::jsonb,'["Colour loss on the fabric: stop and rinse"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Silk, zari, or delicate heirloom fabric: take to a dry cleaner"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['haldi stain','turmeric stain','curry stain','yellow stain','daag','dag','kapde par daag','haldi ka daag','sabzi ka daag','दाग','हल्दी का दाग']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-haldi-stain','summary','Haldi (turmeric) stain on clothes. Turmeric / curry stain on fabric. Act fast: scrape off excess, rinse from the back with cold water, work in liquid detergent, then wash. Drying in sunlight often fades what is left.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-haldi-stain','problem','Yellow haldi or curry stain on clothes, a kurta, or a tablecloth.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-haldi-stain','keywords','haldi stain turmeric stain curry stain yellow stain daag dag kapde par daag haldi ka daag sabzi ka daag दाग हल्दी का दाग');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-oil-stain','Oil or ghee stain on clothes','कपड़े पर तेल का दाग','household','Oil or grease stain on fabric','A greasy spot from cooking oil, ghee, pickle (achaar) or hair oil.',array['adult']::text[],'Adults (keep cleaning products away from children)','Absorb the oil first with talc, cornflour or besan, then work in dishwashing liquid and wash in the warmest water the fabric allows.','limited','Common laundry practice. Dishwashing liquid is designed to break down grease.','["Blot extra oil with a tissue. Do not rub.","Sprinkle talc, cornflour or besan on the spot. Leave 15–30 minutes, then brush off.","Rub a few drops of dishwashing liquid into the stain from both sides.","Wash in the warmest water the care label allows.","Air dry and check. Repeat before ironing if the mark remains."]'::jsonb,'["Ironing or machine drying before the stain is gone.","Petrol or kerosene as a stain remover (fire and fume hazard)."]'::jsonb,'["Fabric damage on delicate materials"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Dry-clean-only garments"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['oil stain','grease stain','grease','greasy','kitchen towel','ghee stain','achaar stain','pickle stain','tel ka daag','chikna daag','तेल का दाग','घी']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-oil-stain','summary','Oil or ghee stain on clothes. Oil or grease stain on fabric. Absorb the oil first with talc, cornflour or besan, then work in dishwashing liquid and wash in the warmest water the fabric allows.');
