insert into public.knowledge_chunks (item_id,kind,content) values ('hh-oil-stain','keywords','oil stain grease stain grease greasy kitchen towel ghee stain achaar stain pickle stain tel ka daag chikna daag तेल का दाग घी');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-tea-stain','Tea or coffee stain','चाय या कॉफ़ी का दाग','household','Tea or coffee stain on fabric','A brown chai or coffee spill on a shirt, sofa cover or tablecloth.',array['adult']::text[],'Adults (keep cleaning products away from children)','Rinse from the back with cold water straight away, then treat with liquid detergent and wash. Older stains may need a soak.','limited','Common laundry practice. Fresh stains come out much more easily than dried ones.','["Blot the spill and rinse from the back under cold water.","Rub in liquid detergent and leave for 10 minutes.","Wash as usual.","For old stains, soak in cool water with detergent for 30 minutes before washing."]'::jsonb,'["Rubbing hard (spreads the stain).","Hot water on milky chai stains (sets the milk protein)."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Upholstery that cannot be removed: follow the manufacturer’s cleaning code"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['tea stain','chai stain','coffee stain','chai ka daag','coffee ka daag','चाय का दाग']::text[]);
