insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-ink-stain','Ink stain on a school uniform','यूनिफ़ॉर्म पर स्याही का दाग','household','Ink stain on fabric','Pen or ink marks on a school shirt, pocket or bedsheet.',array['adult']::text[],'Adults (keep cleaning products away from children)','Dab (do not rub) with a little rubbing alcohol or hand sanitiser on a cotton pad, with a paper towel underneath to absorb the ink, then wash with detergent.','limited','Common laundry practice for ballpoint ink. Test on a hidden area first; alcohol can affect some dyes.','["Put a paper towel under the stain.","Dab with a cotton pad dampened with rubbing alcohol or an alcohol-based sanitiser.","Move to a clean part of the pad as ink lifts. Keep dabbing, do not rub.","Rinse and wash with detergent as usual."]'::jsonb,'["Using alcohol near flames or a gas stove.","Letting children use rubbing alcohol unsupervised."]'::jsonb,'["Colour fading around the stain"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['ink stain','pen stain','ink mark','uniform stain','syahi','siyahi','pen ka daag','स्याही']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-ink-stain','summary','Ink stain on a school uniform. Ink stain on fabric. Dab (do not rub) with a little rubbing alcohol or hand sanitiser on a cotton pad, with a paper towel underneath to absorb the ink, then wash with detergent.');
