insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-fridge-smell','Bad smell in the fridge','फ्रिज से बदबू','household','Fridge odour','A sour or stale smell inside the refrigerator.',array['adult']::text[],'Adults (keep cleaning products away from children)','Find and throw out spoiled food, wipe shelves with warm water and a little baking soda or mild detergent, dry, and leave an open bowl of baking soda inside.','limited','Common household practice. Removing the source is what matters most.','["Check for spoiled food, leaks and forgotten containers. Throw out anything doubtful.","Take out shelves and wipe with warm water plus a spoon of baking soda (or mild detergent).","Clean the drip tray and door seals.","Dry everything before putting it back.","Keep an open bowl of baking soda on a shelf; replace monthly.","Keep cooked food covered."]'::jsonb,'["Strong chemical sprays on food shelves.","Never mix bleach with ammonia, acids (vinegar, lemon, toilet cleaners) or other cleaners. It can release toxic gas."]'::jsonb,'["Food spoiling quickly: the fridge may not be cold enough"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Fridge not staying cold: call a technician (do not open electrical parts yourself)"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['fridge smell','fridge odour','fridge odor','refrigerator smell','fridge badbu','fridge se badbu','fridge mein smell','फ्रिज','बदबू']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-fridge-smell','summary','Bad smell in the fridge. Fridge odour. Find and throw out spoiled food, wipe shelves with warm water and a little baking soda or mild detergent, dry, and leave an open bowl of baking soda inside.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-fridge-smell','problem','A sour or stale smell inside the refrigerator.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-fridge-smell','keywords','fridge smell fridge odour fridge odor refrigerator smell fridge badbu fridge se badbu fridge mein smell फ्रिज बदबू');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-burnt-pan','Burnt kadhai or vessel','जली हुई कड़ाही','household','Burnt cooking vessel','Food or milk burnt onto the bottom of a steel kadhai, pateela or pressure cooker.',array['adult']::text[],'Adults (keep cleaning products away from children)','Cover the burnt layer with water and a spoon of baking soda, simmer for 10 minutes, cool, then scrub. Repeat for stubborn marks.','limited','Common kitchen practice for steel vessels.','["Let the vessel cool completely.","Cover the burnt area with water and add 1–2 spoons of baking soda.","Simmer for about 10 minutes, then let it cool.","Scrub with a scrubber. For stubborn spots, make a paste of baking soda and a little water and leave it for an hour.","Wash with dish soap and rinse well."]'::jsonb,'["Putting cold water into a very hot vessel (can warp it or spit steam).","Steel wool on non-stick pans.","Never mix bleach with ammonia, acids (vinegar, lemon, toilet cleaners) or other cleaners. It can release toxic gas."]'::jsonb,'["Damaged non-stick coating: replace the pan"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Pressure cooker with a damaged gasket, valve or lid: replace parts, do not repair yourself"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['burnt pan','burnt vessel','burnt milk','milk burnt','pateela','patila','bottom of the pot','utensil','burnt kadhai','burnt pot','jala bartan','jali kadhai','bartan jal gaya','doodh jal gaya','जला बर्तन','कड़ाही']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-burnt-pan','summary','Burnt kadhai or vessel. Burnt cooking vessel. Cover the burnt layer with water and a spoon of baking soda, simmer for 10 minutes, cool, then scrub. Repeat for stubborn marks.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-burnt-pan','problem','Food or milk burnt onto the bottom of a steel kadhai, pateela or pressure cooker.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-burnt-pan','keywords','burnt pan burnt vessel burnt milk milk burnt pateela patila bottom of the pot utensil burnt kadhai burnt pot jala bartan jali kadhai bartan jal gaya doodh jal gaya जला बर्तन कड़ाही');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-monsoon-mildew','Monsoon mould and musty smell','बारिश में फफूंद और सीलन','household','Mould and damp during monsoon','Black or green spots on walls, a musty smell in cupboards, or mildew on stored clothes during the rains.',array['adult']::text[],'Adults (keep cleaning products away from children)','Control moisture first: ventilate, dry wet items within 24–48 hours, and fix leaks. Clean small areas of mould on hard surfaces with detergent and water, and dry them thoroughly.','limited','EPA guidance: the key to mould control is moisture control. Damp and mould can affect breathing, especially for people with asthma or allergies (UK government guidance).','["Open windows when it is not raining, and use exhaust fans in kitchens and bathrooms.","Dry wet clothes, towels and shoes within 24–48 hours. Do not pack damp clothes into cupboards.","Leave cupboard doors open for a while on dry days; do not overfill them.","Scrub small mould patches on hard surfaces with detergent and water, then dry completely.","Wear gloves and a mask while cleaning, and keep children away.","Fix leaks and seepage when the rain stops."]'::jsonb,'["Never mix bleach with ammonia, acids (vinegar, lemon, toilet cleaners) or other cleaners. It can release toxic gas.","Painting over mould without fixing the damp.","Sleeping in a room with lots of visible mould if anyone has asthma."]'::jsonb,'["Wheezing, coughing or breathlessness at home, especially in children or people with asthma"]'::jsonb,'[]'::jsonb,'["Breathing difficulty or a severe asthma attack"]'::jsonb,'["Large areas of mould (bigger than roughly a square metre) or mould after flooding: get professional help","Breathing problems that are worse at home"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"A Brief Guide to Mold, Moisture and Your Home","publisher":"US Environmental Protection Agency","url":"https://www.epa.gov/mold/brief-guide-mold-moisture-and-your-home","supports":"Fix moisture, dry items within 24–48 hours; never mix bleach with ammonia."},{"title":"Understanding and addressing the health risks of damp and mould in the home","publisher":"UK Government (GOV.UK guidance)","url":"https://www.nhs.uk/common-health-questions/lifestyle/can-damp-and-mould-affect-my-health/","supports":"Health risks of damp and mould, particularly for respiratory conditions."}]'::jsonb,'government_regulator','2026-09-26','demo_unreviewed','en',array['mould','mold','mildew','musty','musty clothes','clothes smell','smell musty','fungus','damp','musty smell','seelan','silan','fafund','phaphoond','deewar pe kala','monsoon smell','barish','सीलन','फफूंद']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-monsoon-mildew','summary','Monsoon mould and musty smell. Mould and damp during monsoon. Control moisture first: ventilate, dry wet items within 24–48 hours, and fix leaks. Clean small areas of mould on hard surfaces with detergent and water, and dry them thoroughly.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-monsoon-mildew','problem','Black or green spots on walls, a musty smell in cupboards, or mildew on stored clothes during the rains.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-monsoon-mildew','keywords','mould mold mildew musty musty clothes clothes smell smell musty fungus damp musty smell seelan silan fafund phaphoond deewar pe kala monsoon smell barish सीलन फफूंद');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('hh-drain-block','Slow or blocked sink drain','सिंक का पानी रुकना','household','Slow kitchen or bathroom drain','Water draining slowly from a kitchen sink or bathroom basin.',array['adult']::text[],'Adults (keep cleaning products away from children)','Remove visible hair or food from the drain, pour very hot (not boiling, for plastic pipes) water, and use a plunger. Avoid mixing chemical drain cleaners.','limited','Common household practice. Mechanical methods avoid chemical hazards.','["Take out the drain cover and remove hair, food bits or grease you can reach (wear gloves).","Pour a kettle of very hot water down slowly (let it cool a little for plastic pipes).","Use a cup plunger: cover the overflow hole with a wet cloth and plunge firmly 10–15 times.","Clean the trap under the sink over a bucket if the pipe allows.","Prevent it: a strainer on the drain, and do not pour oil or ghee down the sink."]'::jsonb,'["Mixing drain cleaners with each other or with bleach or acid.","Using a plunger right after pouring a chemical drain cleaner (splash risk).","Never mix bleach with ammonia, acids (vinegar, lemon, toilet cleaners) or other cleaners. It can release toxic gas."]'::jsonb,'["Several drains blocked at once, or sewage smell: this may be a main-line issue"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'["Blockage does not clear, or sewage backs up: call a plumber"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"General household practice","publisher":"GharGyaan editorial draft","supports":"Common cleaning practice. No health claim is made. Awaiting editorial review."}]'::jsonb,'general_knowledge','2026-09-26','needs_source','en',array['blocked drain','clogged sink','slow drain','drain block','sink jam','naali band','nali jam','paani nahi ja raha','sink band','नाली','सिंक']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-drain-block','summary','Slow or blocked sink drain. Slow kitchen or bathroom drain. Remove visible hair or food from the drain, pour very hot (not boiling, for plastic pipes) water, and use a plunger. Avoid mixing chemical drain cleaners.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-drain-block','problem','Water draining slowly from a kitchen sink or bathroom basin.');
insert into public.knowledge_chunks (item_id,kind,content) values ('hh-drain-block','keywords','blocked drain clogged sink slow drain drain block sink jam naali band nali jam paani nahi ja raha sink band नाली सिंक');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fd-wash-produce','Washing fruits and vegetables','फल-सब्ज़ी धोना','food','Washing fruits and vegetables safely','How to clean produce, especially leafy greens and fruit eaten raw, and whether to use soap or special washes.',array['adult']::text[],'Adults (keep cleaning products away from children)','Wash produce under clean running water just before eating or cutting. Scrub firm produce with a clean brush. Do not use soap or detergent on fruits and vegetables.','supported','FDA guidance: running water is recommended; soap and detergents can be absorbed by produce and are not recommended. WHO Five Keys also stress safe water and separating raw from cooked.','["Wash hands before handling produce.","Cut away damaged or bruised parts.","Rinse under clean running water, rubbing gently. Scrub firm items (cucumber, potato) with a clean brush.","Separate and rinse leafy greens leaf by leaf, especially palak and dhaniya.","Dry with a clean cloth.","Use a separate board and knife for raw meat and for produce eaten raw."]'::jsonb,'["Soap, detergent, or dishwashing liquid on produce.","Washing well before storing (extra moisture speeds spoilage)."]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,null,null,null,null,null,'self_care','[{"title":"Selecting and Serving Produce Safely","publisher":"US Food and Drug Administration","url":"https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-produce-safely","supports":"Wash produce under running water; do not use soap or detergent on produce."},{"title":"Five keys to safer food manual","publisher":"World Health Organization","url":"https://www.who.int/publications/i/item/9789241594639","supports":"Keep clean, separate raw and cooked, cook thoroughly, keep food at safe temperatures, use safe water."}]'::jsonb,'government_regulator','2026-09-26','demo_unreviewed','en',array['wash vegetables','wash fruits','clean vegetables','vegetable wash','sabzi dhona','sabji dhona','phal dhona','soap on vegetables','सब्ज़ी धोना','फल धोना']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-wash-produce','summary','Washing fruits and vegetables. Washing fruits and vegetables safely. Wash produce under clean running water just before eating or cutting. Scrub firm produce with a clean brush. Do not use soap or detergent on fruits and vegetables.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-wash-produce','problem','How to clean produce, especially leafy greens and fruit eaten raw, and whether to use soap or special washes.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-wash-produce','keywords','wash vegetables wash fruits clean vegetables vegetable wash sabzi dhona sabji dhona phal dhona soap on vegetables सब्ज़ी धोना फल धोना');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('fd-leftovers','Storing leftovers safely','बचे हुए खाने को सुरक्षित रखना','food','Storing and reheating leftovers','Keeping dal, rice, sabzi and other cooked food safe to eat later, especially in hot weather.',array['adult']::text[],'Adults (keep cleaning products away from children)','Cool cooked food quickly, cover it and refrigerate promptly. Do not leave cooked food out at room temperature for long, and reheat until it is steaming hot all the way through.','supported','WHO Five Keys to Safer Food: keep food at safe temperatures, separate raw and cooked, cook thoroughly. The UK Food Standards Agency advises chilling food properly to stop harmful bacteria growing. Exact storage times vary; this guide is general.','["Cool cooked food quickly: spread it in a shallow container instead of leaving a big pot to cool.","Cover and refrigerate as soon as it has cooled.","Keep raw and cooked food separate in the fridge.","Reheat until steaming hot throughout. Stir so there are no cold spots.","Rice needs special care: cool and refrigerate it quickly, and do not keep it warm for hours.","When in doubt, throw it out."]'::jsonb,'["Leaving cooked rice, dal or meat out for hours in the heat.","Reheating the same food again and again.","Tasting food to check if it has gone bad."]'::jsonb,'["Sour smell, froth, slime or mould: throw it away"]'::jsonb,'[]'::jsonb,'["Vomiting with blurred or double vision, drooping eyelids or difficulty swallowing after eating home-preserved food"]'::jsonb,'["Vomiting and diarrhoea after eating: follow the dehydration guide; see a doctor for blood in stool, high fever or signs of dehydration"]'::jsonb,null,null,null,null,null,'self_care','[{"title":"Five keys to safer food manual","publisher":"World Health Organization","url":"https://www.who.int/publications/i/item/9789241594639","supports":"Keep clean, separate raw and cooked, cook thoroughly, keep food at safe temperatures, use safe water."},{"title":"How to chill, freeze and defrost food safely","publisher":"Food Standards Agency (UK)","url":"https://www.food.gov.uk/safety-hygiene/chilling","supports":"Cooling and refrigerating leftovers promptly."},{"title":"Food safety (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/food-safety","supports":"Keeping food at safe temperatures and preventing contamination."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['leftovers','leftover food','store food','reheat','basi khana','baasi khana','raat ka khana','bacha khana','rice leftover','food storage','बासी खाना','बचा खाना']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-leftovers','summary','Storing leftovers safely. Storing and reheating leftovers. Cool cooked food quickly, cover it and refrigerate promptly. Do not leave cooked food out at room temperature for long, and reheat until it is steaming hot all the way through.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-leftovers','problem','Keeping dal, rice, sabzi and other cooked food safe to eat later, especially in hot weather.');
insert into public.knowledge_chunks (item_id,kind,content) values ('fd-leftovers','keywords','leftovers leftover food store food reheat basi khana baasi khana raat ka khana bacha khana rice leftover food storage बासी खाना बचा खाना');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('se-summer-heat','Summer heat and loo','गर्मी और लू से बचाव','seasonal','Feeling unwell in the heat','Feeling dizzy, very thirsty, sweaty, headachy or weak in hot weather or after being out in the sun.',array['adult','child','older_adult']::text[],'All ages (babies, children and older adults at higher risk)','Move to a cool place, remove extra clothing, drink water or ORS, and cool the skin with water and fanning. Heat exhaustion should improve within 30 minutes. If not, treat it as heatstroke: an emergency.','supported','NHS guidance on heat exhaustion and heatstroke, and on coping in hot weather.','["Move to a cool, shaded place.","Remove unnecessary clothing.","Drink plenty of water. ORS helps replace salts lost in sweat.","Cool the skin: sponge or spray with cool water and fan. Wrapped cold packs under the armpits or on the neck help.","Stay with the person. They should feel better within 30 minutes.","Prevent it: avoid the sun in the hottest hours, wear light loose cotton, carry water, keep rooms shaded."]'::jsonb,'["Alcohol and lots of caffeine in the heat.","Heavy exercise in the midday sun.","Leaving anyone, especially children, in a parked vehicle."]'::jsonb,'["Symptoms not improving after 30 minutes of cooling","Confusion or unusual behaviour"]'::jsonb,'["People with heart or kidney conditions, or on water tablets, should ask their doctor about fluids in hot weather."]'::jsonb,'["Still unwell after 30 minutes of cooling and fluids","Very high temperature, or hot skin that is not sweating","Confusion, poor coordination, fast breathing","Seizure (fit) or loss of consciousness"]'::jsonb,'["Symptoms you are struggling to manage","A baby, young child or older adult affected by heat"]'::jsonb,'[{"practice":"Aam panna, nimbu-paani, chaas, sattu drink in summer","evidence":"limited","note":"Good traditional ways to take in fluids and some salt. For someone who is already unwell with heat, ORS is more reliable.","safety":"Watch the sugar and salt: very sweet or salty drinks are not ideal for rehydration."},{"practice":"Pyaaz (onion) in the pocket to prevent loo","evidence":"traditional","note":"A folk belief. There is no evidence it protects against heat illness.","safety":"Harmless, but must not replace shade, water and rest."}]'::jsonb,'{"infant":"Babies overheat quickly. Keep them out of direct sun, dress lightly, and keep feeding. Seek help if they are drowsy or feeding poorly.","older_adult":"Older adults may not feel thirsty. Check on elderly relatives and neighbours in heatwaves."}'::jsonb,null,'[{"id":"severe","text":"Any confusion, fainting, a fit, or hot dry skin without sweating?","text_hi":"क्या उलझन, बेहोशी, दौरा, या बिना पसीने के गर्म सूखी त्वचा है?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"These are signs of heatstroke. Call 112 now and keep cooling them."}]}]'::jsonb,null,'self_care','[{"title":"Heat exhaustion and heatstroke","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/heat-exhaustion-heatstroke/","supports":"Cooling steps, fluids, and heatstroke emergency signs."},{"title":"Heatwave: how to cope in hot weather","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/live-well/seasonal-health/heatwave-how-to-cope-in-hot-weather/","supports":"Staying out of the heat, keeping homes cool, checking on vulnerable people."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['heat','heatwave','heat wave','keep cool','stay cool','hot day','heatstroke','heat stroke','heat exhaustion','sunstroke','summer','hot weather','loo','loo lag gayi','loo lagna','garmi','garmi lag gayi','dhoop','chakkar garmi','लू','गर्मी','धूप']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('se-summer-heat','summary','Summer heat and loo. Feeling unwell in the heat. Move to a cool place, remove extra clothing, drink water or ORS, and cool the skin with water and fanning. Heat exhaustion should improve within 30 minutes. If not, treat it as heatstroke: an emergency.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-summer-heat','problem','Feeling dizzy, very thirsty, sweaty, headachy or weak in hot weather or after being out in the sun.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-summer-heat','keywords','heat heatwave heat wave keep cool stay cool hot day heatstroke heat stroke heat exhaustion sunstroke summer hot weather loo loo lag gayi loo lagna garmi garmi lag gayi dhoop chakkar garmi लू गर्मी धूप');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('se-monsoon-mosquitoes','Monsoon mosquito protection','बारिश में मच्छरों से बचाव','seasonal','Preventing mosquito bites in monsoon','Protecting the family from mosquitoes that spread dengue and malaria during and after the rains.',array['adult','child','older_adult','infant']::text[],'All ages','Stop mosquitoes breeding by emptying and covering stored water weekly, and prevent bites with covering clothes, nets, screens and repellents.','supported','WHO dengue guidance: cover, empty and clean domestic water containers weekly; use clothing, nets, screens and repellents containing DEET, picaridin or IR3535.','["Once a week, empty and scrub coolers, flower-pot trays, buckets, tyres and anything holding water.","Cover water tanks and stored water.","Wear long sleeves and full pants, especially at dawn and dusk (dengue mosquitoes also bite in the day).","Sleep under a mosquito net, including for daytime naps for babies.","Use window screens and a repellent containing DEET, picaridin or IR3535, following the label for age."]'::jsonb,'["Letting water collect in coolers, pots and terraces.","Burning coils in closed rooms with children or people with asthma."]'::jsonb,'["Fever, severe body ache, pain behind the eyes, rash in the week after bites"]'::jsonb,'["Check repellent labels for age limits before using on babies and young children."]'::jsonb,'["Fever with severe tummy pain, repeated vomiting, bleeding gums or nose, blood in vomit or stool","Fever with extreme tiredness, restlessness or fast breathing"]'::jsonb,'["Any fever during dengue/malaria season: see a doctor for testing","Do not self-medicate a fever with ibuprofen or aspirin during dengue season: ask a doctor"]'::jsonb,'[{"practice":"Neem leaf smoke or neem oil to keep mosquitoes away","evidence":"limited","note":"Neem has some repellent activity in small studies, but is less proven than standard repellents.","safety":"Smoke irritates lungs, especially for children and people with asthma. Use nets and screens as the main protection."},{"practice":"Papaya leaf juice for dengue","evidence":"limited","note":"Widely shared. Some small studies exist, but it is not a treatment for dengue.","safety":"Never delay seeing a doctor for fever in dengue season."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Dengue and severe dengue (fact sheet)","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/dengue-and-severe-dengue","supports":"Covering skin, nets, repellents (DEET, picaridin, IR3535), emptying stored water weekly."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['mosquito','mosquitoes','dengue','malaria','monsoon','rainy season','mosquito prevention','repellent','cooler water','machhar se bachav','machhar bhagao','barish','baarish','dengu','मच्छर','डेंगू','मलेरिया','बारिश']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('se-monsoon-mosquitoes','summary','Monsoon mosquito protection. Preventing mosquito bites in monsoon. Stop mosquitoes breeding by emptying and covering stored water weekly, and prevent bites with covering clothes, nets, screens and repellents.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-monsoon-mosquitoes','problem','Protecting the family from mosquitoes that spread dengue and malaria during and after the rains.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-monsoon-mosquitoes','keywords','mosquito mosquitoes dengue malaria monsoon rainy season mosquito prevention repellent cooler water machhar se bachav machhar bhagao barish baarish dengu मच्छर डेंगू मलेरिया बारिश');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('se-winter-dry-skin','Winter dry skin','सर्दियों में रूखी त्वचा','seasonal','Dry, itchy winter skin','Dry, rough, flaky or itchy skin, cracked heels or chapped lips in winter.',array['adult','child','older_adult']::text[],'All ages','Keep baths short and warm (not hot), pat dry, and apply a moisturising cream or ointment within minutes of bathing. Use gentle, fragrance-free products.','supported','American Academy of Dermatology tips: short warm showers, moisturise right after, ointments or creams, gentle fragrance-free products, a humidifier.','["Limit baths to 5–10 minutes with warm, not hot, water.","Pat skin dry gently with a towel.","Apply moisturiser within a few minutes of bathing, while skin is still slightly damp.","Ointments and creams work better than lotions for very dry skin.","Use lip balm or petroleum jelly on lips.","Choose gentle, fragrance-free soap and moisturiser."]'::jsonb,'["Very hot water baths.","Harsh or strongly perfumed soaps.","Scratching dry patches."]'::jsonb,'["Cracks that bleed or become red and sore","Itching that disturbs sleep"]'::jsonb,'[]'::jsonb,'["Red, hot, swollen skin with fever (possible infection)","Widespread rash with blisters"]'::jsonb,'["No improvement after a couple of weeks","Intense itching or cracking and bleeding","Signs of infection"]'::jsonb,'[{"practice":"Coconut oil or sarson (mustard) oil massage before bath","evidence":"limited","note":"Plant oils can help seal moisture into skin. Coconut oil is a common moisturiser.","safety":"Mustard oil can irritate sensitive skin and is not advised on babies’ faces. Patch-test first."},{"practice":"Malai (milk cream) or ghee on chapped lips","evidence":"traditional","note":"Traditional and gentle, but not better than a plain lip balm or petroleum jelly.","safety":"Usually harmless. Avoid if it causes irritation."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Dermatologists'' top tips for relieving dry skin","publisher":"American Academy of Dermatology","url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin","supports":"Short warm showers, moisturise straight after, humidifier, gentle products."}]'::jsonb,'professional_society','2026-09-26','demo_unreviewed','en',array['dry skin','itchy skin','itching','itch','winter skin','chapped lips','cracked heels','flaky skin','rukhi twacha','rukhi skin','khujli sardi','phate hont','fati ediyan','एड़ियाँ','रूखी त्वचा','फटे होंठ']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('se-winter-dry-skin','summary','Winter dry skin. Dry, itchy winter skin. Keep baths short and warm (not hot), pat dry, and apply a moisturising cream or ointment within minutes of bathing. Use gentle, fragrance-free products.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-winter-dry-skin','problem','Dry, rough, flaky or itchy skin, cracked heels or chapped lips in winter.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-winter-dry-skin','keywords','dry skin itchy skin itching itch winter skin chapped lips cracked heels flaky skin rukhi twacha rukhi skin khujli sardi phate hont fati ediyan एड़ियाँ रूखी त्वचा फटे होंठ');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('wl-screen-fatigue','Screen fatigue and tired eyes','स्क्रीन से आँखों की थकान','wellness','Tired eyes from screens','Dry, tired, aching eyes or blurred vision after long hours on a laptop or phone.',array['adult','child','older_adult']::text[],'All ages','Blink often, look up and into the distance regularly, sit about an arm’s length from the screen, and reduce glare. Digital eye strain is uncomfortable but does not permanently damage eyes.','supported','American Academy of Ophthalmology: screen use does not permanently damage eyes; blinking, breaks, screen distance and glare control help.','["Make a habit of blinking: we blink much less while looking at screens.","Every so often, look up and at something far away for a little while.","Sit about 25 inches (an arm’s length) from the screen, with the screen slightly below eye level.","Reduce glare: adjust brightness to match the room, avoid a bright window behind the screen.","A pharmacist can suggest lubricating eye drops for dryness."]'::jsonb,'["Using screens in a dark room.","Rubbing eyes."]'::jsonb,'["Headaches or blurred vision that continue after screen time","Needing to hold things very close or very far to read"]'::jsonb,'[]'::jsonb,'["Sudden loss of vision","Eye pain with redness and light sensitivity","Flashes of light or a curtain over vision"]'::jsonb,'["Blurred vision that does not clear with rest: get an eye test","A child squinting or holding screens very close"]'::jsonb,'[{"practice":"Rose water (gulab jal) or cucumber on tired eyes","evidence":"traditional","note":"May feel refreshing. Not a treatment for eye strain.","safety":"Do not put non-sterile liquids into the eyes. Use only on closed eyelids."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Computers, Digital Devices, and Eye Strain","publisher":"American Academy of Ophthalmology","url":"https://www.aao.org/eye-health/tips-prevention/computer-usage","supports":"Blink more, look up and into the distance regularly, sit about an arm’s length from the screen, reduce glare."}]'::jsonb,'professional_society','2026-09-26','demo_unreviewed','en',array['eye strain','tired eyes','screen time','screen fatigue','dry eyes','computer eyes','laptop','aankh mein dard','aankhen thak gayi','aankhon mein jalan','mobile se aankh','आँखों में दर्द','आँख','स्क्रीन']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-screen-fatigue','summary','Screen fatigue and tired eyes. Tired eyes from screens. Blink often, look up and into the distance regularly, sit about an arm’s length from the screen, and reduce glare. Digital eye strain is uncomfortable but does not permanently damage eyes.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-screen-fatigue','problem','Dry, tired, aching eyes or blurred vision after long hours on a laptop or phone.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-screen-fatigue','keywords','eye strain tired eyes screen time screen fatigue dry eyes computer eyes laptop aankh mein dard aankhen thak gayi aankhon mein jalan mobile se aankh आँखों में दर्द आँख स्क्रीन');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('wl-poor-sleep','Poor sleep','नींद ठीक से न आना','wellness','Trouble sleeping','Trouble falling asleep, waking up at night, or not feeling rested, for a few nights or weeks.',array['adult','older_adult']::text[],'Adults','Keep regular sleep and wake times, wind down for an hour before bed without screens, keep the room dark, quiet and cool, and limit caffeine and heavy meals in the evening.','supported','NHS guidance on sleep and on tiredness: regular routines, a restful bedroom, avoiding screens, caffeine, alcohol and heavy meals before bed.','["Get up at the same time every day, even after a bad night.","Wind down for an hour before bed: dim lights, read, listen to music, or try slow breathing.","Keep the room dark, quiet and not too warm.","Stop caffeine (tea, coffee, cola) by mid-afternoon.","Avoid heavy meals, exercise and alcohol in the couple of hours before bed.","If you cannot sleep after about 20 minutes, get up and do something calm, then return to bed."]'::jsonb,'["Screens in bed.","Long daytime naps.","Using alcohol as a sleep aid.","Buying sleeping pills without a doctor."]'::jsonb,'["Sleep problems lasting weeks","Low mood, worry or stress keeping you awake"]'::jsonb,'[]'::jsonb,'["Loud snoring with gasping or choking during sleep","Thoughts of self-harm or hopelessness"]'::jsonb,'["Poor sleep for several weeks despite changes","It affects daily life, work or driving","Snoring with gasping or pauses in breathing"]'::jsonb,'[{"practice":"Warm milk, or a foot massage with oil (padabhyanga), before bed","evidence":"traditional","note":"Part of calming bedtime routines in many homes. A relaxing routine helps sleep; the specific remedy is not proven.","safety":"Generally harmless."},{"practice":"Pranayama / slow breathing before sleep","evidence":"limited","note":"Slow, relaxed breathing is a common relaxation technique that may help you wind down.","safety":"Keep it gentle. Stop if you feel dizzy."}]'::jsonb,null,null,null,null,'self_care','[{"title":"Sleep (Every Mind Matters)","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/every-mind-matters/mental-health-issues/sleep/","supports":"Regular sleep routine and wind-down habits."},{"title":"Tiredness and fatigue","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/tiredness-and-fatigue/","supports":"Sleep routine, activity, when tiredness needs a GP."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['sleep','insomnia','cannot sleep','can''t sleep','poor sleep','sleepless','waking at night','neend','neend nahi aati','neend nahi aa rahi','raat ko neend','so nahi pata','नींद','नींद नहीं']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-poor-sleep','summary','Poor sleep. Trouble sleeping. Keep regular sleep and wake times, wind down for an hour before bed without screens, keep the room dark, quiet and cool, and limit caffeine and heavy meals in the evening.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-poor-sleep','problem','Trouble falling asleep, waking up at night, or not feeling rested, for a few nights or weeks.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-poor-sleep','keywords','sleep insomnia cannot sleep can''t sleep poor sleep sleepless waking at night neend neend nahi aati neend nahi aa rahi raat ko neend so nahi pata नींद नींद नहीं');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('wl-neck-stiffness','Stiff neck from desk work or sleeping','गर्दन में अकड़न','wellness','Neck stiffness','A stiff, sore neck after sleeping awkwardly or long hours at a desk or phone.',array['adult','older_adult']::text[],'Adults','Keep the neck gently moving, use heat or cold packs, sit upright, and use a low firm pillow. Most neck pain eases within a few weeks.','supported','NHS neck pain guidance: keep moving, heat or cold packs, posture, pillow height.','["Keep your neck moving gently. Try slow neck turns and tilts within comfort.","Cold pack (frozen peas in a towel) for 5 minutes, 3 times a day, or a wrapped hot water bottle for 20 minutes, 2–3 times a day.","Sit upright, roll your shoulders back gently, and bring the screen to eye level.","Take a break from the same position every 30–60 minutes.","Use a low, firm pillow; avoid sleeping on your front."]'::jsonb,'["Wearing a neck collar unless a doctor advises.","Driving or cycling if you cannot turn your head."]'::jsonb,'["Pins and needles or weakness in the arm","Pain not easing after a few weeks"]'::jsonb,'[]'::jsonb,'["Stiff neck with fever and a headache, or bright light hurting the eyes","Neck pain after a fall or accident","Numbness or weakness in arms or legs, or loss of bladder control"]'::jsonb,'["Pain or stiffness lasting more than a few weeks","Painkillers are not helping","Other symptoms like pins and needles"]'::jsonb,null,null,null,'[{"id":"fever","text":"Is there a fever with a headache, or does bright light hurt the eyes?","text_hi":"क्या बुखार और सिरदर्द है, या तेज़ रोशनी से आँखों में दिक्कत?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Stiff neck with fever and headache needs emergency care (possible meningitis)."}]},{"id":"injury","text":"Did it start after a fall or accident?","options":[{"label":"No","value":"no"},{"label":"Yes","value":"yes","escalate":"urgent","reason":"Neck pain after an injury needs medical assessment. Keep the neck still."}]}]'::jsonb,null,'self_care','[{"title":"Neck pain","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/neck-pain/","supports":"Keeping the neck moving, heat/cold packs, posture at a desk."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['stiff neck','neck pain','neck stiffness','desk neck','cervical','gardan','gardan akad gayi','gardan mein dard','gardan dard','गर्दन','गर्दन में दर्द','अकड़न']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-neck-stiffness','summary','Stiff neck from desk work or sleeping. Neck stiffness. Keep the neck gently moving, use heat or cold packs, sit upright, and use a low firm pillow. Most neck pain eases within a few weeks.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-neck-stiffness','problem','A stiff, sore neck after sleeping awkwardly or long hours at a desk or phone.');
insert into public.knowledge_chunks (item_id,kind,content) values ('wl-neck-stiffness','keywords','stiff neck neck pain neck stiffness desk neck cervical gardan gardan akad gayi gardan mein dard gardan dard गर्दन गर्दन में दर्द अकड़न');
insert into public.knowledge_items (id,title,title_hi,category,situation_label,problem,audience,age_range,modern_guidance,evidence_level,evidence_summary,how_to,what_to_avoid,watch_for,contraindications,red_flags,when_to_seek_help,traditional_use,audience_notes,not_for,clarify,myth,safety_level,source,source_type,last_reviewed,review_status,language,keywords) values ('se-heat-rash','Heat rash (ghamoriyan) and minor skin irritation','घमौरियाँ','seasonal','Heat rash or minor skin irritation','Small, itchy, prickly red or skin-coloured spots in hot, sweaty weather, often on the neck, back or chest.',array['adult','child','older_adult','infant']::text[],'All ages','Keep the skin cool so it does not sweat: loose cotton clothes, light bedding, cool baths and plenty of fluids. Heat rash usually settles on its own in a few days.','supported','NHS guidance on heat rash: keep skin cool, cold compress, pat instead of scratching, avoid perfumed products; a pharmacist can suggest treatments.','["Wear loose cotton clothing and use light bedding.","Take cool baths or showers.","Drink plenty of fluids.","For itching: a damp cloth or wrapped ice pack for up to 20 minutes.","Tap or pat the skin instead of scratching.","A pharmacist can suggest calamine lotion or other treatments suitable for the person’s age."]'::jsonb,'["Perfumed soaps, shower gels and creams.","Thick oils or heavy creams that block sweat.","Hydrocortisone cream for children under 10 without a doctor’s advice."]'::jsonb,'["Rash not improving after a few days","Spots becoming painful, filled with pus, or spreading"]'::jsonb,'[]'::jsonb,'["A rash that does not fade when a glass is pressed on it, especially with fever","Rash with swelling of the face or lips, or trouble breathing","A baby with a rash who is unwell, floppy, or has a high temperature"]'::jsonb,'["Not improving after a few days","A baby has a rash and you are worried","Signs of infection"]'::jsonb,'[{"practice":"Prickly heat powder, multani mitti or sandalwood (chandan) paste","evidence":"traditional","note":"Cooling pastes and powders are traditional in Indian summers. Keeping skin cool and dry is what the evidence supports.","safety":"Avoid talc near a baby’s face (breathing it in). Stop anything that stings or worsens the rash."}]'::jsonb,'{"infant":"Babies get heat rash easily because they cannot control temperature well. Dress them lightly. If a baby with a rash seems unwell, see a doctor."}'::jsonb,null,'[{"id":"glass","text":"Does the rash fade when you press a clear glass against it? Any fever?","text_hi":"क्या गिलास दबाने पर दाने फीके पड़ते हैं? क्या बुखार है?","options":[{"label":"It fades, no fever","value":"fades"},{"label":"It does not fade, or there is a fever with it","value":"nonblanch","escalate":"urgent","reason":"A rash that does not fade under a glass, especially with fever, needs emergency care."}]}]'::jsonb,null,'self_care','[{"title":"Heat rash (prickly heat)","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/heat-rash-prickly-heat/","supports":"Keep skin cool, loose cotton, cold compress, pat instead of scratching; see a GP if not improving."},{"title":"Rashes in babies and children","publisher":"NHS (UK National Health Service)","url":"https://www.nhs.uk/conditions/skin-rash-children/","supports":"Rash that does not fade under a glass with fever needs emergency care."}]'::jsonb,'public_health_body','2026-09-26','demo_unreviewed','en',array['heat rash','prickly heat','rash','itching','itchy','itch','skin rash','red spots','itchy spots','skin irritation','ghamori','ghamoriyan','ghamauri','ghamoriya','daane','dane','lal daane','khujli daane','घमौरियाँ','दाने','चकत्ते']::text[]);
insert into public.knowledge_chunks (item_id,kind,content) values ('se-heat-rash','summary','Heat rash (ghamoriyan) and minor skin irritation. Heat rash or minor skin irritation. Keep the skin cool so it does not sweat: loose cotton clothes, light bedding, cool baths and plenty of fluids. Heat rash usually settles on its own in a few days.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-heat-rash','problem','Small, itchy, prickly red or skin-coloured spots in hot, sweaty weather, often on the neck, back or chest.');
insert into public.knowledge_chunks (item_id,kind,content) values ('se-heat-rash','keywords','heat rash prickly heat rash itching itchy itch skin rash red spots itchy spots skin irritation ghamori ghamoriyan ghamauri ghamoriya daane dane lal daane khujli daane घमौरियाँ दाने चकत्ते');
